        "everyday|2:1|3|p3": "ମୁଁ ଲାଉଡସ୍ପିକର ଅନ କରୁଛି, ଯାହା ଫଳରେ ମୋ ବାପାମା ମଧ୍ୟ ଶୁଣିପାରିବେ।",
        "everyday|2:1|3|p4": "ଏଠି ସଂଯୋଗ ବହୁତ ଖରାପ; ଦୟାକରି ଶେଷ ଅଂଶଟି ପୁଣି କହିବେ କି?",
        "everyday|2:1|4|title": "ପ୍ରାୟ ହାତଛଡ଼ା ହୋଇଥିବା କଲ",
        "everyday|2:1|4|text": "ରବି ପୁଣେର ଏକ କମ୍ପାନୀରୁ ଗୋଟିଏ ଜରୁରୀ କଲକୁ ଅପେକ୍ଷା କରୁଥିଲେ। ତାଙ୍କ ଫୋନ ବାଜିଲା, କିନ୍ତୁ ଫୋନ କରିଥିବା ଲୋକ ସୁରେଶ ନାମରେ କାହାକୁ ଖୋଜିଲେ। ରବି ଭଦ୍ର ଭାବେ ତାଙ୍କୁ କହିଲେ ଯେ ସେ ଭୁଲ ନମ୍ବରରେ ଫୋନ କରିଛନ୍ତି। କିଛି ମିନିଟ ପରେ, ସେ ଯେତେବେଳେ ଲିଫ୍ଟରେ ଥିଲେ, କମ୍ପାନୀରୁ ଗୋଟିଏ ମିସ୍ଡ କଲ ଆସିଲା। ସେ ତୁରନ୍ତ ସେହି ନମ୍ବର ଡାଏଲ କଲେ, କିନ୍ତୁ ଲାଇନ ବ୍ୟସ୍ତ ଥିଲା। ତା'ପରେ ତାଙ୍କ ବ୍ୟାଟେରି ପାଞ୍ଚ ପ୍ରତିଶତକୁ ଖସିଗଲା, ଆଉ ଚାର୍ଜରଟି ସେ ଘରେ ଛାଡ଼ି ଆସିଥିଲେ। ଜଣେ ଦୟାଳୁ ଦୋକାନୀ ତାଙ୍କୁ ଚାର୍ଜର ବ୍ୟବହାର କରିବାକୁ ଦେଲେ, ଆଉ ଶେଷରେ ତାଙ୍କ କଲ ଲାଗିଲା। ମ୍ୟାନେଜର ହସିଲେ ଏବଂ କହିଲେ ଯେ ସେ ନିଜେ ତାଙ୍କୁ ଫୋନ କରିବାକୁ ଯାଉଥିଲେ।",
        "everyday|2:1|4|q0": "ପ୍ରଥମ ଫୋନରେ ଲୋକଟି କାହାକୁ ଖୋଜୁଥିଲେ?",
        "everyday|2:1|4|q0o0": "ସୁରେଶ ନାମରେ ଜଣେ ଲୋକଙ୍କୁ",
