        "everyday|2:1|5|title": "ମେସେଜ ଛାଡ଼ିବା",
        "everyday|2:1|5|scenario": "ଅନିଲ ମଙ୍ଗଳୁରୁର ଏକ ଟ୍ରାଭେଲ ଏଜେନ୍ସିକୁ ଶ୍ରୀ କାମତଙ୍କ ସହ କଥା ହେବା ପାଇଁ ଫୋନ କରନ୍ତି, ଆଉ ରିସେପ୍ସନିଷ୍ଟ ପୂଜା ଫୋନ ଉଠାନ୍ତି।",
        "everyday|2:1|5|l0": "ନମସ୍କାର, କୋଷ୍ଟାଲ ଟ୍ରାଭେଲସ, ମୁଁ ପୂଜା କହୁଛି। କହନ୍ତୁ, କି ସାହାଯ୍ୟ କରିପାରିବି?",
