        "everyday|2:1|5|l3": "ହଁ, ଦୟାକରି। ଗୋଆ ଯାତ୍ରା ବିଷୟରେ ମୋତେ ପୁଣି ଫୋନ କରିବାକୁ ତାଙ୍କୁ କହିବେ କି?",
        "everyday|2:1|5|l4": "ଦୁଃଖିତ, ଲାଇନ ବହୁତ ଖରାପ। ଦୟାକରି ପୁଣି ଥରେ କହିବେ କି?",
        "everyday|2:1|5|l5": "ନିଶ୍ଚୟ। ଦୟାକରି ଶ୍ରୀ କାମତଙ୍କୁ ଗୋଆ ଯାତ୍ରା ବିଷୟରେ ମୋତେ ପୁଣି ଫୋନ କରିବାକୁ କହିବେ।",
        "everyday|2:1|5|l6": "ନିଶ୍ଚୟ। ଆପଣଙ୍କୁ କେଉଁ ନମ୍ବରରେ ସହଜରେ ପାଇହେବ?",
        "everyday|2:1|5|l7": "ଆପଣ ମୋତେ 98450 12376 ନମ୍ବରରେ ପାଇପାରିବେ।",
        "everyday|2:1|5|l8": "ମୁଁ ଥରେ ପଢ଼ି ଶୁଣାଉଛି: 98450 12376। ସେ ମେସେଜଟି ନିଶ୍ଚୟ ପାଇବେ, ମୁଁ ଦେଖିବି।",
        "everyday|2:1|5|l9": "ହଁ, ଠିକ। ଆପଣଙ୍କ ସାହାଯ୍ୟ ପାଇଁ ବହୁତ ଧନ୍ୟବାଦ।",
        "everyday|2:1|5|q0": "ଅନିଲ ଶ୍ରୀ କାମତଙ୍କ ସହ କାହିଁକି କଥା ହୋଇପାରୁନାହାନ୍ତି?",
