        "everyday|3:1|0|w0": "ଖାତା",
        "everyday|3:1|0|w1": "ନଗଦ ଟଙ୍କା",
        "everyday|3:1|0|w2": "ଟଙ୍କା ଉଠାଇବା",
        "everyday|3:1|0|w3": "ପାସବୁକ",
        "everyday|3:1|0|w4": "ଚେକ",
        "everyday|3:1|0|w5": "ବାଲାନ୍ସ",
        "everyday|3:1|1|p0": "ମୁଁ ମୋ ଝିଅ ନାଁରେ ଏକ ସେଭିଂସ ଖାତା ଖୋଲିବାକୁ ଚାହେଁ।",
        "everyday|3:1|1|p1": "ନଗଦ ଟଙ୍କା ଜମା କରିବାକୁ ଚାହୁଁଥିଲେ ଦୟାକରି ଏହି ସ୍ଲିପ ପୂରଣ କରନ୍ତୁ।",
        "everyday|3:1|1|p2": "ଚେକ ବିନା ଗୋଟିଏ ଦିନରେ ମୁଁ କେତେ ଟଙ୍କା ଉଠାଇପାରିବି?",
        "everyday|3:1|1|p3": "ଦୟାକରି ମୋ ପାସବୁକ ଅପଡେଟ କରିଦେବେ କି? ମାସ ମାସ ହେଲା ଏହା ପ୍ରିଣ୍ଟ ହୋଇନାହିଁ।",
        "everyday|3:1|1|p4": "ମୋ ବାଲାନ୍ସ ବହୁତ କମ, ତେଣୁ ଡର ଲାଗୁଛି ଚେକ ବାଉନ୍ସ ହୋଇଯାଇପାରେ।",
        "everyday|3:1|2|w0": "ଏଟିଏମ",
        "everyday|3:1|2|w1": "ଡେବିଟ କାର୍ଡ",
        "everyday|3:1|2|w2": "ପିନ",
        "everyday|3:1|2|w3": "ୟୁପିଆଇ",
        "everyday|3:1|2|w4": "ସୁଧ",
        "everyday|3:1|2|w5": "କେୱାଇସି",
        "everyday|3:1|3|p0": "ଏଟିଏମ ମୋ ଡେବିଟ କାର୍ଡ ରଖିଦେଲା, ତେଣୁ ମୋତେ ତୁରନ୍ତ ତାହା ବ୍ଲକ କରିବାକୁ ପଡ଼ିବ।",
        "everyday|3:1|3|p1": "କେହି ବ୍ୟାଙ୍କରୁ କହୁଛି ବୋଲି କହିଲେ ବି, ନିଜ ପିନ କାହାକୁ କେବେ ବି କୁହନ୍ତୁ ନାହିଁ।",
        "everyday|3:1|3|p2": "ମୁଁ ୟୁପିଆଇରେ ଭଡ଼ା ଦେଇଦେଲି, କିନ୍ତୁ ଏବେ ବି ତାହା ମାଲିକଙ୍କ ପାଖରେ ପହଞ୍ଚିନାହିଁ।",
        "everyday|3:1|3|p3": "ଦୁଇ ବର୍ଷର ଫିକ୍ସଡ ଡିପୋଜିଟରେ ଆପଣ କେତେ ସୁଧ ଦିଅନ୍ତି?",
        "everyday|3:1|3|p4": "ଦୟାକରି ଆଧାର ଓ ପାନ ଦେଇ ଆପଣଙ୍କ କେୱାଇସି ସମ୍ପୂର୍ଣ୍ଣ କରନ୍ତୁ, ନଚେତ ଖାତା ବନ୍ଦ ହୋଇଯାଇପାରେ।",
        "everyday|3:1|4|title": "ପ୍ରଥମ ବ୍ୟାଙ୍କ ଖାତା",
        "everyday|3:1|4|text": "ସଞ୍ଜନା ମଙ୍ଗଳୁରୁରେ ତାଙ୍କ ପ୍ରଥମ ଚାକିରି ପାଇଲେ ଏବଂ ସାଲାରି ଖାତା ଖୋଲିବାକୁ ପାଖରେ ଥିବା ଏକ ବ୍ୟାଙ୍କକୁ ଗଲେ। କେୱାଇସି ପାଇଁ ଅଫିସର ତାଙ୍କ ଆଧାର କାର୍ଡ, ପାନ କାର୍ଡ ଓ ଦୁଇଟି ଫଟୋ ମାଗିଲେ। ସଞ୍ଜନା ଫର୍ମ ପୂରଣ କଲେ ଏବଂ ଦୁଇ ହଜାର ଟଙ୍କା ଜମା କଲେ। ଗୋଟିଏ ସପ୍ତାହ ପରେ ସେ ଏକ ପାସବୁକ, ଚେକ ବୁକ ଓ ଡେବିଟ କାର୍ଡ ପାଇଲେ। ଅଫିସର ତାଙ୍କୁ ଏଟିଏମରେ ନୂଆ ପିନ ସେଟ କରିବାକୁ ଏବଂ ତାହା କାହାକୁ କେବେ ନ କହିବାକୁ କହିଲେ। ସେ ନିଜ ଫୋନରେ ଖାତାକୁ ୟୁପିଆଇ ସହ ମଧ୍ୟ ଯୋଡ଼ିଲେ। ଏବେ ସେ ପ୍ରତି ମାସରେ ବାଲାନ୍ସ ଦେଖନ୍ତି ଏବଂ ସୁଧ ପାଇବା ପାଇଁ କିଛି ଟଙ୍କା ଫିକ୍ସଡ ଡିପୋଜିଟରେ ରଖନ୍ତି।",
        "everyday|3:1|4|q0": "ସଞ୍ଜନା କାହିଁକି ଖାତା ଖୋଲିଲେ?",
        "everyday|3:1|4|q0o0": "ଦରମା ପାଇବା ପାଇଁ",
        "everyday|3:1|4|q0o1": "ଲୋନ ନେବା ପାଇଁ",
        "everyday|3:1|4|q0o2": "କଲେଜ ଫି ଦେବା ପାଇଁ",
        "everyday|3:1|4|q0o3": "ବିଦେଶକୁ ଟଙ୍କା ପଠାଇବା ପାଇଁ",
        "everyday|3:1|4|q1": "ପ୍ରଥମେ ସେ କେତେ ଟଙ୍କା ଜମା କଲେ?",
        "everyday|3:1|4|q1o0": "ଦୁଇ ହଜାର ଟଙ୍କା",
        "everyday|3:1|4|q1o1": "ପାଞ୍ଚ ଶହ ଟଙ୍କା",
