        "everyday|3:1|4|q2": "ପିନ ବିଷୟରେ ଅଫିସର କ'ଣ କହିଲେ?",
        "everyday|3:1|4|q2o0": "ତାହା କାହାକୁ କେବେ ନ କହିବା",
        "everyday|3:1|4|q2o1": "ତାହା କାର୍ଡ ଉପରେ ଲେଖିବା",
