        "everyday|3:1|4|q2o3": "ପ୍ରତିଦିନ ତାହା ବଦଳାଇବା",
        "everyday|3:1|5|title": "ବିଫଳ ପେମେଣ୍ଟ",
        "everyday|3:1|5|scenario": "ଗୋଟିଏ ୟୁପିଆଇ ପେମେଣ୍ଟ ବିଫଳ ହେବାରୁ ଫରହାନ ପୁଣେରେ ତାଙ୍କ ବ୍ୟାଙ୍କକୁ ଯାଆନ୍ତି ଏବଂ ହେଲ୍ପ ଡେସ୍କରେ ରିତୁଙ୍କ ସହ କଥା ହୁଅନ୍ତି।",
        "everyday|3:1|5|l0": "ସୁପ୍ରଭାତ, ସାର। ଆଜି ମୁଁ ଆପଣଙ୍କୁ କିପରି ସାହାଯ୍ୟ କରିପାରିବି?",
        "everyday|3:1|5|l1": "ସୁପ୍ରଭାତ। କାଲି ମୁଁ ୟୁପିଆଇରେ ତିନି ହଜାର ଟଙ୍କା ଦେଇଥିଲି, କିନ୍ତୁ ପେମେଣ୍ଟ ବିଫଳ ହୋଇଗଲା।",
        "everyday|3:1|5|l2": "ଆଚ୍ଛା। ଆପଣଙ୍କ ଖାତାରୁ ଟଙ୍କା କଟିଛି କି?",
        "everyday|3:1|5|l3": "ହଁ। ମୋ ବାଲାନ୍ସ କମିଗଲା, କିନ୍ତୁ ଦୋକାନୀ ଟଙ୍କା ପାଇଲେ ନାହିଁ।",
        "everyday|3:1|5|l4": "ଚିନ୍ତା କରନ୍ତୁ ନାହିଁ। ବିଫଳ ପେମେଣ୍ଟର ଟଙ୍କା ସାଧାରଣତଃ ତିନି କାର୍ଯ୍ୟ ଦିବସ ଭିତରେ ଫେରିଆସେ।",
        "everyday|3:1|5|l5": "ଯାହା ହେଉ, ଆଶ୍ୱସ୍ତ ହେଲି। ଏଠି ଆସିଛି ଯେତେବେଳେ, ଶିକ୍ଷା ଲୋନ ବିଷୟରେ ଟିକେ କହିବେ କି?",
        "everyday|3:1|5|l6": "ନିଶ୍ଚୟ। ସୁଧ ହାର ପ୍ରାୟ ନଅ ପ୍ରତିଶତ, ଆଉ ଆପଣଙ୍କ କେୱାଇସି ଅପଡେଟ ଥିବା ଦରକାର।",
        "everyday|3:1|5|l7": "ମୋତେ ଲାଗୁଛି ତାହା ସମ୍ପୂର୍ଣ୍ଣ ଅଛି। ଗତ ବର୍ଷ ମୁଁ ମୋ ଆଧାର ବିବରଣୀ ଅପଡେଟ କରିଥିଲି।",
        "everyday|3:1|5|l8": "ମୁଁ ଦେଖୁଛି। ହଁ, ସବୁ ଠିକ ଅଛି। ଏଇ ନିଅନ୍ତୁ ଲୋନ ଫର୍ମ ଆଉ ଦରକାରୀ କାଗଜପତ୍ରର ତାଲିକା।",
        "everyday|3:1|5|l9": "ବହୁତ ଧନ୍ୟବାଦ। ଆପଣ ବହୁତ ସାହାଯ୍ୟ କଲେ।",
