        "everyday|4:1|1|p0": "ଶୁଣନ୍ତୁ, ଦୟାକରି ଆମକୁ ମେନୁ ଆଉ ଟିକେ ପାଣି ଦେବେ କି?",
        "everyday|4:1|1|p1": "ୱେଟର ନୀର ଦୋସା ଖାଇବାକୁ କହିଲେ, ତେଣୁ ଆମେ ଦୁଇ ପ୍ଲେଟ ଅର୍ଡର କଲୁ।",
        "everyday|4:1|1|p2": "ଆମେ ଗୋଟିଏ ଷ୍ଟାର୍ଟର ବାଣ୍ଟି ଖାଇବା, ତା'ପରେ ନିଜ ନିଜର ମୁଖ୍ୟ ଖାଦ୍ୟ ଅର୍ଡର କରିବା କି?",
        "everyday|4:1|1|p3": "ମୋ ପେଟ ଏତେ ଭରିଗଲାଣି ଯେ ମିଠା ଖାଇପାରିବି ନାହିଁ, କିନ୍ତୁ ଗୋଟିଏ ଫିଲ୍ଟର କଫି ପିଇବାକୁ ଭଲ ଲାଗିବ।",
        "everyday|4:1|1|p4": "ଆମ ପାଇଁ ଆଉ କିଛି ନାପକିନ ଏବଂ ମୋ ପୁଅ ପାଇଁ ଗୋଟିଏ ଛୋଟ ଚାମଚ ଆଣିଦେବେ କି?",
