        "everyday|4:1|2|w5": "ଭାଗ",
        "everyday|4:1|3|p0": "ମୋର ବାଦାମରେ ଆଲର୍ଜି ଅଛି, ତେଣୁ ଏହି ତରକାରିର ଉପାଦାନ ଟିକେ ଯାଞ୍ଚ କରିଦେବେ କି?",
        "everyday|4:1|3|p1": "ଆମେ ସମସ୍ତେ ଶାକାହାରୀ, ତେଣୁ ଦୟାକରି ଦେଖିବେ କୌଣସି ଖାଦ୍ୟରେ ଅଣ୍ଡା ନ ଥାଉ।",
        "everyday|4:1|3|p2": "ଏହାକୁ ଟିକେ କମ ରାଗ କରିପାରିବେ କି? ମୋ ପୁଅ ବେଶି ଲଙ୍କା ସହିପାରେ ନାହିଁ।",
        "everyday|4:1|3|p3": "ଏଠି ଖାଦ୍ୟର ଭାଗ ବହୁତ ବେଶି, ତେଣୁ ବାକିତକ ପାର୍ସଲ କରିଦେବେ କି?",
        "everyday|4:1|3|p4": "ବିଲରେ ଆଗରୁ ସର୍ଭିସ ଚାର୍ଜ ଯୋଡ଼ା ହୋଇଛି, ତେଣୁ ବକସିସ ଦେବା ଦରକାର ନାହିଁ।",
        "everyday|4:1|4|title": "ଉଡୁପିରେ ଜନ୍ମଦିନର ଭୋଜି",
        "everyday|4:1|4|text": "ଜେଜେମାଙ୍କର ଅଶୀ ବର୍ଷ ପୂରିବା ଜନ୍ମଦିନ ପାଇଁ କିରଣ ଉଡୁପିର ଏକ ଲୋକପ୍ରିୟ ରେଷ୍ଟୁରାଣ୍ଟରେ ଟେବୁଲ ବୁକ କଲେ। ୱେଟର ମେନୁ ଆଣିଲେ ଏବଂ ଷ୍ଟାର୍ଟର ଭାବେ ପନିର ଟିକ୍କା ନେବାକୁ କହିଲେ। କିରଣଙ୍କ ମାମୁଁ ଝିଅ ନିଶାଙ୍କର ଚିନାବାଦାମରେ ଆଲର୍ଜି ଅଛି, ତେଣୁ କିରଣ ୱେଟରଙ୍କୁ ପ୍ରତ୍ୟେକ ଖାଦ୍ୟ ଭଲ ଭାବେ ଯାଞ୍ଚ କରିବାକୁ କହିଲେ। ଜେଜେମା ତାଙ୍କ ମୁଖ୍ୟ ଖାଦ୍ୟ କମ ରାଗ ଚାହୁଁଥିଲେ, ଆଉ ରୋଷେୟା ଖୁସିରେ ରାଜି ହେଲେ। ମିଠା ପାଇଁ ପୁରା ପରିବାର ଗୋଟିଏ ବଡ଼ ଗଡ଼ବଡ଼ ଆଇସକ୍ରିମ ବାଣ୍ଟି ଖାଇଲେ। ବିଲ ଆସିବା ପରେ କିରଣ ଦେଖିଲେ ଯେ ପାଞ୍ଚ ପ୍ରତିଶତ ସର୍ଭିସ ଚାର୍ଜ ଆଗରୁ ଯୋଡ଼ା ହୋଇଛି। ତଥାପି ସେ ଟିକେ ବକସିସ ଛାଡ଼ିଲେ, କାରଣ ୱେଟର ସେମାନଙ୍କ ସହ ବହୁତ ଧୈର୍ଯ୍ୟ ଧରିଥିଲେ। ବଳକା ରୁଟିଗୁଡ଼ିକ ସେମାନେ ପାର୍ସଲ କରି ଘରକୁ ନେଇଗଲେ।",
        "everyday|4:1|4|q0": "କିରଣ ୱେଟରଙ୍କୁ ପ୍ରତ୍ୟେକ ଖାଦ୍ୟ ଯାଞ୍ଚ କରିବାକୁ କାହିଁକି କହିଲେ?",
        "everyday|4:1|4|q0o0": "ତାଙ୍କ ମାମୁଁ ଝିଅଙ୍କର ଚିନାବାଦାମରେ ଆଲର୍ଜି ଅଛି",
        "everyday|4:1|4|q0o1": "ତାଙ୍କ ଜେଜେମା ଶାକାହାରୀ",
