        "everyday|5:1|1|p0": "ମୁଁ ମାର୍ଚ୍ଚ ପାଞ୍ଚ ତାରିଖରୁ ଦୁଇ ରାତି ପାଇଁ ବୁକିଂ କରିବାକୁ ଚାହେଁ।",
        "everyday|5:1|1|p1": "ଏହି ସପ୍ତାହାନ୍ତ ପାଇଁ ଡବଲ ରୁମ ଉପଲବ୍ଧ ଅଛି କି ନାହିଁ ଦେଖିଦେବେ କି?",
        "everyday|5:1|1|p2": "ଚେକ-ଇନ ଦିନ ବାରଟାରେ, କିନ୍ତୁ ଆପଣ ଆଗରୁ ଆପଣଙ୍କ ବ୍ୟାଗ ଆମ ପାଖରେ ରଖିପାରିବେ।",
