        "everyday|5:1|3|p4": "ଏଗାରଟା ପରେ ରୁମ ସର୍ଭିସ ମିଳେ କି, ନା ସେତେବେଳକୁ ରୋଷେଇଘର ବନ୍ଦ ହୋଇଯାଏ?",
        "everyday|5:1|4|title": "ମଡ଼ିକେରିରେ ଏକ କୋଳାହଳପୂର୍ଣ୍ଣ ରାତି",
        "everyday|5:1|4|text": "ନିଖିଲ ଓ ତାଙ୍କ ସ୍ତ୍ରୀ ଶ୍ରେୟା ଲମ୍ବା ସପ୍ତାହାନ୍ତ ପାଇଁ ମଡ଼ିକେରିର ଏକ ଛୋଟ ହୋଟେଲରେ ବୁକିଂ କଲେ। ଚେକ-ଇନ ବେଳେ ରିସେପ୍ସନିଷ୍ଟ ସେମାନଙ୍କୁ ତଳ ମହଲାରେ ଏକ ଡବଲ ରୁମ ଦେଲେ। ସେଦିନ ରାତିରେ ଏସିରୁ ଜୋର ଖଡ଼ଖଡ଼ ଶବ୍ଦ ହେଲା, ଆଉ ରୁମଟି ଶୋଇବା ପାଇଁ ବହୁତ ଗରମ ଥିଲା। ନିଖିଲ ଫ୍ରଣ୍ଟ ଡେସ୍କକୁ ଫୋନ କରି ଭଦ୍ର ଭାବେ ଅଭିଯୋଗ କଲେ। ମ୍ୟାନେଜର କ୍ଷମା ମାଗିଲେ ଏବଂ ସେମାନଙ୍କୁ ଉପର ମହଲାର ଏକ ଶାନ୍ତ ରୁମକୁ ପଠାଇଲେ, ଯେଉଁଠୁ ପାହାଡ଼ ଦେଖାଯାଉଥିଲା। ପରଦିନ ସକାଳେ ହାଉସକିପିଂ କର୍ମଚାରୀ ନ ମାଗୁଣୁ ସଫା ତଉଲିଆ ଓ ଅତିରିକ୍ତ ତକିଆ ଆଣିଦେଲେ। ଚେକ-ଆଉଟ ବେଳେ ଅସୁବିଧା ପାଇଁ କ୍ଷତିପୂରଣ ଭାବେ ମ୍ୟାନେଜର ସେମାନଙ୍କୁ ମାଗଣା ଜଳଖିଆ ଦେଲେ।",
