        "everyday|5:1|5|l5": "ବଢ଼ିଆ। ଲିଫ୍ଟଠାରୁ ଦୂରରେ ଗୋଟିଏ ରୁମ ମିଳିପାରିବ କି? ଟିକେ ଶବ୍ଦ ହେଲେ ମୋ ନିଦ ଭାଙ୍ଗିଯାଏ।",
