        "everyday|6:1|1|p0": "ଚାଲୁକ୍ୟ ଏକ୍ସପ୍ରେସ କେଉଁ ପ୍ଲାଟଫର୍ମରୁ ଛାଡ଼େ?",
        "everyday|6:1|1|p1": "ମୋତେ ଲୋୟର ବର୍ଥ ହେଲେ ଭଲ, କାରଣ ମୋ ବାପାଙ୍କୁ ଉପରକୁ ଚଢ଼ିବାରେ କଷ୍ଟ ହୁଏ।",
        "everyday|6:1|1|p2": "ଆମ ଟିକଟ ଏବେ ବି ୱେଟିଂ ଲିଷ୍ଟରେ ଅଛି, ତେଣୁ ହୁଏତ ସିଟ ମିଳିବ ନାହିଁ।",
        "everyday|6:1|1|p3": "ଦୀପାବଳିର ଅତି କମରେ ଏକ ମାସ ଆଗରୁ ଆପଣ ରିଜର୍ଭେସନ କରିବା ଉଚିତ।",
        "everyday|6:1|1|p4": "ପୁଣେ ପର୍ଯ୍ୟନ୍ତ ସ୍ଲିପର ବଗିର ଭଡ଼ା ପ୍ରାୟ ଛଅ ଶହ ଟଙ୍କା।",
