        "everyday|6:1|3|p0": "ଦିଲ୍ଲୀ ପାଖରେ ଘନ କୁହୁଡ଼ି ଯୋଗୁଁ ଚାରି ଘଣ୍ଟା ବିଳମ୍ବ ହେଉଛି।",
        "everyday|6:1|3|p1": "ଦୁଇ ଦିନରୁ ଅଧିକ ଆଗରୁ ବାତିଲ କଲେ, ବାତିଲ ଚାର୍ଜ କମ ଲାଗେ।",
        "everyday|6:1|3|p2": "ବସ ବାତିଲ ହୋଇଗଲା, ତେଣୁ ମୁଁ ଟଙ୍କା ଫେରସ୍ତ ମାଗିବାକୁ ଏନକ୍ୱାଇରି କାଉଣ୍ଟରକୁ ଗଲି।",
        "everyday|6:1|3|p3": "ସେହି ଘୋଷଣା ଶୁଣିଲ କି? ଆମକୁ ଆମ ମାଲପତ୍ର ପାଞ୍ଚ ନମ୍ବର ପ୍ଲାଟଫର୍ମକୁ ନେବାକୁ ପଡ଼ିବ।",
        "everyday|6:1|3|p4": "ସମୟ ସାରଣୀ ଅନୁସାରେ, ମହୀଶୂରକୁ ଶେଷ ବସ ଦଶଟାରେ ଛାଡ଼େ।",
        "everyday|6:1|4|title": "ଠିକ ସମୟରେ",
        "everyday|6:1|4|text": "ଆଶା ତାଙ୍କ ଭଉଣୀର ବାହାଘର ପାଇଁ ହୁବ୍ବଳିରୁ ପୁଣେ ଯାଉଥିଲେ। ସେ ଦୁଇ ମାସ ଆଗରୁ ରିଜର୍ଭେସନ କରିଥିଲେ ଏବଂ ଏସ-4 ବଗିରେ ତାଙ୍କର ଲୋୟର ବର୍ଥ ଥିଲା। ଷ୍ଟେସନରେ ଘୋଷଣା ହେଲା ଯେ ଟ୍ରେନ ତିନି ଘଣ୍ଟା ବିଳମ୍ବରେ ଚାଲିଛି। ଆଶା ନିଜ ଫୋନରେ ବସର ସମୟ ସାରଣୀ ଦେଖିଲେ ଏବଂ ଗୋଟିଏ ବସ ପାଇଲେ ଯାହା ପୁଣେ ଶୀଘ୍ର ପହଞ୍ଚିବ। ସେ ଅନଲାଇନରେ ଟ୍ରେନ ଟିକଟ ବାତିଲ କଲେ, ଆଉ ଦୁଇ ଦିନରେ ଟଙ୍କା ତାଙ୍କ ଖାତାକୁ ଫେରିଆସିଲା। ଜଣେ କୁଲି ଅଳ୍ପ ପଇସାରେ ତାଙ୍କ ଭାରି ବ୍ୟାଗଗୁଡ଼ିକ ବସ ଷ୍ଟାଣ୍ଡ ପର୍ଯ୍ୟନ୍ତ ନେଇଗଲା। ସେ ଠିକ ମେହେନ୍ଦି ସମୟକୁ ପୁଣେ ପହଞ୍ଚିଗଲେ।",
        "everyday|6:1|4|q0": "ଆଶା କାହିଁକି ପୁଣେ ଯାଉଥିଲେ?",
