        "everyday|6:1|5|title": "ବାତିଲ ହୋଇଥିବା ଟ୍ରେନ",
        "everyday|6:1|5|scenario": "ମହୀଶୂର ରେଳ ଷ୍ଟେସନରେ କବିତା ଜାଣିପାରନ୍ତି ଯେ ବେଙ୍ଗାଲୁରୁ ଯିବା ତାଙ୍କ ଟ୍ରେନ ବାତିଲ ହୋଇଛି, ଏବଂ ସେ ଏନକ୍ୱାଇରି କାଉଣ୍ଟରରେ ସୁରେଶଙ୍କୁ ସାହାଯ୍ୟ ମାଗନ୍ତି।",
        "everyday|6:1|5|l0": "ଶୁଣନ୍ତୁ, ମୁଁ ଏଇନେ ଘୋଷଣା ଶୁଣିଲି ଯେ ଚାମୁଣ୍ଡି ଏକ୍ସପ୍ରେସ ବାତିଲ ହୋଇଛି। ଏହା ସତ କି?",
        "everyday|6:1|5|l1": "ହଁ, ଦୁଃଖର କଥା, ମାଡାମ। ମାଣ୍ଡ୍ୟା ପାଖରେ ରେଳ ଲାଇନରେ ସମସ୍ୟା ଅଛି।",
        "everyday|6:1|5|l2": "ହାୟ। ଦୁଇଟାରେ ବେଙ୍ଗାଲୁରୁରେ ମୋର ଗୋଟିଏ ଜରୁରୀ ମିଟିଂ ଅଛି। ମୋ ପାଇଁ କି ଉପାୟ ଅଛି?",
        "everyday|6:1|5|l3": "ତିନି ନମ୍ବର ପ୍ଲାଟଫର୍ମରୁ ଏଗାରଟା ପନ୍ଦରରେ ଗୋଟିଏ ଏକ୍ସପ୍ରେସ ଅଛି। ସାଧାରଣତଃ ତାହା ଦେଢ଼ଟା ସୁଦ୍ଧା ପହଞ୍ଚେ।",
        "everyday|6:1|5|l4": "ସେଥିରେ କିଛି ସିଟ ବାକି ଅଛି କି?",
        "everyday|6:1|5|l5": "କେବଳ ଜେନେରାଲ ବଗିରେ, ମାଡାମ। ରିଜର୍ଭ ସିଟ ସବୁ ୱେଟିଂ ଲିଷ୍ଟରେ ଅଛି।",
        "everyday|6:1|5|l6": "ଜେନେରାଲ ବଗି ଚଳିବ। ଆଉ ମୋ ବାତିଲ ହୋଇଥିବା ଟିକଟର କ'ଣ ହେବ?",
        "everyday|6:1|5|l7": "ଯେହେତୁ ରେଳବାଇ ଟ୍ରେନଟି ବାତିଲ କରିଛି, ଆପଣ ଏକ ସପ୍ତାହ ଭିତରେ ପୁରା ଟଙ୍କା ଫେରସ୍ତ ପାଇବେ।",
        "everyday|6:1|5|l8": "ଟଙ୍କା ଫେରସ୍ତ ପାଇଁ ମୋତେ କିଛି ଫର୍ମ ପୂରଣ କରିବାକୁ ପଡ଼ିବ କି?",
        "everyday|6:1|5|l9": "ନା, ମାଡାମ। ଆପଣ ଅନଲାଇନରେ ବୁକ କରିଥିବାରୁ ଏହା ନିଜେ ନିଜେ ହୋଇଯିବ। ଆପଣଙ୍କ ଯାତ୍ରା ଶୁଭ ହେଉ।",
        "everyday|6:1|5|q0": "ଚାମୁଣ୍ଡି ଏକ୍ସପ୍ରେସ କାହିଁକି ବାତିଲ ହେଲା?",
