        "everyday|6:1|5|q1": "ସୁରେଶ କେଉଁ ଟ୍ରେନ ବିଷୟରେ କହନ୍ତି?",
        "everyday|6:1|5|q1o0": "ଏଗାରଟା ପନ୍ଦରର ଏକ୍ସପ୍ରେସ",
