        "everyday|6:1|5|q2": "କବିତା କିପରି ତାଙ୍କ ଟଙ୍କା ଫେରି ପାଇବେ?",
        "everyday|6:1|5|q2o0": "ନିଜେ ନିଜେ, ପୁରା ଟଙ୍କା ଫେରସ୍ତ ଭାବେ",
