        "opinions|2:1|1|p1": "ଏହା ଠିକ କଥା; ମୁଁ ଖର୍ଚ୍ଚ ବିଷୟରେ ଭାବି ନ ଥିଲି।",
        "opinions|2:1|1|p2": "ମୁଁ ପୂରାପୂରି ସହମତ; ରବିବାର ଦିନ ଲାଇବ୍ରେରୀ ଖୋଲା ରହିବା ଉଚିତ।",
        "opinions|2:1|1|p3": "ମୁଁ ସ୍ୱୀକାର କରୁଛି ଯେ ତୁମେ ଠିକ ଥିଲ; ସକଲେଶପୁର ଦେଇ ରାସ୍ତାଟି ବହୁତ ଶୀଘ୍ର ଥିଲା।",
        "opinions|2:1|1|p4": "କିଛି ମାତ୍ରାରେ ତୁମେ ଠିକ, କିନ୍ତୁ ଚାଲ ସହମତିର ଆଧାର ଖୋଜିବା।",
        "opinions|2:1|2|w0": "ସମ୍ମାନର ସହ",
        "opinions|2:1|2|w1": "ଭିନ୍ନମତ ରଖିବା",
        "opinions|2:1|2|w2": "ପୁନର୍ବିଚାର କରିବା",
        "opinions|2:1|2|w3": "ମନ ବଦଳିବା",
        "opinions|2:1|2|w4": "ଉଦାର ମନର",
        "opinions|2:1|2|w5": "ମତଭେଦ ମାନିନେବା",
        "opinions|2:1|3|p0": "ସମ୍ମାନର ସହ କହୁଛି, ସାର, ମୋତେ ଲାଗୁଛି ତଥ୍ୟ ଅଲଗା କଥା କହୁଛି।",
        "opinions|2:1|3|p1": "ମୁଁ ଭିନ୍ନମତ ରଖୁଛି; ମଲଠାରୁ ପୁରୁଣା ବଜାରର ନିଜସ୍ୱ ରୂପ ବହୁତ ବେଶି।",
        "opinions|2:1|3|p2": "ଦୁଇ ପକ୍ଷର କଥା ଶୁଣିବା ପରେ ପ୍ରଧାନଶିକ୍ଷୟିତ୍ରୀ ତାଙ୍କ ନିଷ୍ପତ୍ତି ପୁନର୍ବିଚାର କରିବାକୁ ରାଜି ହେଲେ।",
        "opinions|2:1|3|p3": "ପ୍ରଥମେ ସେ ଯାତ୍ରାର ବିରୋଧରେ ଥିଲେ, କିନ୍ତୁ ତା'ପରେ ତାଙ୍କ ମନ ବଦଳିଗଲା।",
        "opinions|2:1|3|p4": "ଆମେ ଦୁହେଁ ଉଦାର ମନର, ତେଣୁ ଆମେ ସହଜରେ ମତଭେଦ ମାନିନେଇପାରିବା।",
        "opinions|2:1|4|title": "ଶେଷ ସ୍କୁଲ ଯାତ୍ରା",
        "opinions|2:1|4|text": "ହାସନରେ ଦ୍ୱାଦଶ ଶ୍ରେଣୀର ଛାତ୍ରଛାତ୍ରୀଙ୍କୁ ସେମାନଙ୍କ ଶେଷ ସ୍କୁଲ ଯାତ୍ରା ପାଇଁ ଏକ ଜାଗା ବାଛିବାର ଥିଲା। ନିଖିଲ ସମୁଦ୍ର କୂଳ ପାଇଁ ଗୋକର୍ଣ୍ଣ ଚାହୁଁଥିଲେ, କିନ୍ତୁ ଦିବ୍ୟା ଇତିହାସ ପାଇଁ ହମ୍ପି ଚାହୁଁଥିଲେ। ପ୍ରଥମେ ଦୁହେଁ ଏକମତ ହେଲେ ନାହିଁ, ଆଉ ଆଲୋଚନା ଜୋରରେ ହେବାକୁ ଲାଗିଲା। ତା'ପରେ ଦିବ୍ୟା କହିଲେ, 'ସମ୍ମାନର ସହ କହୁଛି, ସମୁଦ୍ର କୂଳ ମଜାଦାର, କିନ୍ତୁ ହମ୍ପି ଏମିତି ଜିନିଷ ଯାହା ଆମେ ସାରା ଜୀବନ ମନେରଖିବା।' ନିଖିଲ ସ୍ୱୀକାର କଲେ ଯେ ତାଙ୍କ କଥା ଠିକ, କିନ୍ତୁ ସେ ଗରମକୁ ନେଇ ଚିନ୍ତିତ ଥିଲେ। ସେମାନଙ୍କ ଶିକ୍ଷକ ସହମତିର ଆଧାର ଖୋଜିବାରେ ସାହାଯ୍ୟ କଲେ: ସେମାନେ ଥଣ୍ଡା ସକାଳେ ହମ୍ପି ବୁଲିବେ ଏବଂ ଅପରାହ୍ନରେ ତୁଙ୍ଗଭଦ୍ରା ନଦୀ କୂଳରେ ବିଶ୍ରାମ ନେବେ। ଶେଷରେ ନିଖିଲଙ୍କ ମନ ବଦଳିଗଲା ଏବଂ ସେ ନିଜେ ହମ୍ପି ପାଇଁ ଭୋଟ ଦେଲେ। ଏକ ମାସ ପରେ ସମସ୍ତେ ସହମତ ହେଲେ ଯେ ଏହା ସେମାନଙ୍କ ଜୀବନର ସବୁଠାରୁ ଭଲ ଯାତ୍ରା ଥିଲା।",
        "opinions|2:1|4|q0": "ନିଖିଲ କାହିଁକି ଗୋକର୍ଣ୍ଣ ଯିବାକୁ ଚାହୁଁଥିଲେ?",
        "opinions|2:1|4|q0o0": "ସମୁଦ୍ର କୂଳ ପାଇଁ",
        "opinions|2:1|4|q0o1": "ମନ୍ଦିର ପାଇଁ",
