        "opinions|2:1|4|q2": "ଶିକ୍ଷକ ସେମାନଙ୍କୁ କେଉଁ ଯୋଜନାରେ ରାଜି କରାଇଲେ?",
        "opinions|2:1|4|q2o0": "ସକାଳେ ହମ୍ପି, ଅପରାହ୍ନରେ ନଦୀ କୂଳରେ ବିଶ୍ରାମ",
        "opinions|2:1|4|q2o1": "ଦିନେ ଗୋକର୍ଣ୍ଣ ଆଉ ଦିନେ ହମ୍ପି",
        "opinions|2:1|4|q2o2": "ହାସନରେ ରହି ଏକ ସଂଗ୍ରହାଳୟ ଦେଖିବା",
        "opinions|2:1|4|q2o3": "କେବଳ ରାତିରେ ହମ୍ପି ବୁଲିବା",
        "opinions|2:1|5|title": "କଲେଜ ଫେଷ୍ଟର ଯୋଜନା",
        "opinions|2:1|5|scenario": "ମଙ୍ଗଳୁରୁର ଏକ କଲେଜର ଫେଷ୍ଟ କମିଟିରେ ଥିବା ଦୁଇ ଛାତ୍ର ପୂଜା ଓ ସମୀର, ଟଙ୍କା କିପରି ଖର୍ଚ୍ଚ କରାଯିବ ସେ ବିଷୟରେ ଅସହମତ।",
        "opinions|2:1|5|l0": "ସମୀର, ମୁଁ ଶୁଣିଲି ତୁମେ କଲେଜ ଫେଷ୍ଟକୁ ଜଣେ ସିନେମା ତାରକାଙ୍କୁ ଡାକିବାକୁ ଚାହୁଁଛ। ଏହା ସତ କି?",
        "opinions|2:1|5|l1": "ହଁ! ବଡ଼ ନାଁ ଆସିଲେ ବହୁତ ଭିଡ଼ ହେବ। ତୁମକୁ ସେମିତି ଲାଗୁନାହିଁ?",
        "opinions|2:1|5|l2": "କିଛି ମାତ୍ରାରେ, ହଁ। କିନ୍ତୁ ସମ୍ମାନର ସହ କହୁଛି, ତାରକାଙ୍କ ଫି ଆମ ଅଧା ଟଙ୍କା ଖାଇଯିବ।",
        "opinions|2:1|5|l3": "ଏହା ଠିକ କଥା। ତଥାପି, ତାରକା ବିନା ଫେଷ୍ଟ ଟିକେ ସାଧାରଣ ଲାଗେ।",
        "opinions|2:1|5|l4": "ମୁଁ ଭିନ୍ନମତ ରଖୁଛି। ଗତ ବର୍ଷ ଉଡୁପିର ଯକ୍ଷଗାନ ଦଳ ଫେଷ୍ଟର ସବୁଠାରୁ ଭଲ ଅଂଶ ଥିଲା।",
        "opinions|2:1|5|l5": "ହୁଁ, ସେହି ଶୋ ବିଷୟରେ ମୁଁ ପୂରାପୂରି ସହମତ। ଶେଷରେ ସମସ୍ତେ ନାଚୁଥିଲେ।",
        "opinions|2:1|5|l6": "ତେବେ ସେମାନଙ୍କୁ ପୁଣି ଡାକି, ବାକି ଟଙ୍କା ଭଲ ଖାଦ୍ୟ ଆଉ ଆଲୁଅ ପାଇଁ ଖର୍ଚ୍ଚ କରିବା ନାହିଁ କାହିଁକି?",
        "opinions|2:1|5|l7": "ଠିକ ଅଛି, ତୁମେ ମୋ ମନ ବଦଳାଇଦେଲ। ମୁଁ ପୁନର୍ବିଚାର କରିବି ଏବଂ କାଲି କମିଟି ସହ କଥା ହେବି।",
        "opinions|2:1|5|l8": "ଏତେ ଉଦାର ମନର ହୋଇଥିବାରୁ ଧନ୍ୟବାଦ। ମୁଁ ଜାଣେ ଏହା ତୁମର ପ୍ରିୟ ଆଇଡିଆ ଥିଲା।",
        "opinions|2:1|5|l9": "ହଉ, କେଉଁ ସିନେମା ତାରକା ସବୁଠାରୁ ଭଲ, ସେ ବିଷୟରେ ଆମେ ମତଭେଦ ମାନିନେଇପାରିବା!",
        "opinions|2:1|5|q0": "ସମୀର ଫେଷ୍ଟ ପାଇଁ କ'ଣ ଚାହୁଁଥିଲେ?",
        "opinions|2:1|5|q0o0": "ଜଣେ ସିନେମା ତାରକାଙ୍କୁ ଡାକିବା",
