        "opinions|3:1|0|w5": "ଅସ୍ପଷ୍ଟ ଭାବେ",
        "opinions|3:1|1|p0": "ପୁରୁଣା ସିନେମା ଗୀତ ସବୁବେଳେ ମୋ ଜେଜେମାଙ୍କୁ ଅତୀତର ସ୍ମୃତିରେ ଭରିଦିଏ।",
        "opinions|3:1|1|p1": "ମୋ ପିଲାଦିନେ, ଅନ୍ଧାର ହେବା ପର୍ଯ୍ୟନ୍ତ ଆମେ ପଡ଼ିଆରେ ଖେଳୁଥିଲୁ।",
        "opinions|3:1|1|p2": "ସ୍କୁଲରେ ମୋ ପ୍ରଥମ ଦିନର ସ୍ମୃତି ଏବେ ବି ମୋ ମନରେ ଜୀବନ୍ତ ଅଛି।",
        "opinions|3:1|1|p3": "ମୋ ମାମୁଁମାନେ ଯେତେବେଳେ ଭେଟନ୍ତି, ଧାରୱାଡ଼ରେ ସେମାନଙ୍କ କଲେଜ ଦିନର ପୁରୁଣା କଥା ମନେପକାନ୍ତି।",
        "opinions|3:1|1|p4": "ମଙ୍ଗଳୁରୁର ଯେଉଁ ଘରେ ମୁଁ ଜନ୍ମ ହୋଇଥିଲି, ତାହା ମୋର କେବଳ ଅସ୍ପଷ୍ଟ ଭାବେ ମନେ ଅଛି।",
        "opinions|3:1|2|w0": "ସ୍କୁଲ ଦିନ",
        "opinions|3:1|2|w1": "ଅବିସ୍ମରଣୀୟ",
        "opinions|3:1|2|w2": "ଜୀବନର ମୋଡ଼",
        "opinions|3:1|2|w3": "ଦୁଷ୍ଟାମି",
        "opinions|3:1|2|w4": "ସ୍ମୃତିଚିହ୍ନ",
        "opinions|3:1|2|w5": "ହଠାତ ମନେପଡ଼ିବା",
        "opinions|3:1|3|p0": "ବେଳଗାଭିରେ ମୋ ସ୍କୁଲ ଦିନ ମୋ ଜୀବନର ସବୁଠାରୁ ଖୁସିର ବର୍ଷ ଥିଲା।",
        "opinions|3:1|3|p1": "ଆନ୍ତଃ-ସ୍କୁଲ କୁଇଜ ଜିତିବା ଆମ ପୁରା କ୍ଲାସ ପାଇଁ ଏକ ଅବିସ୍ମରଣୀୟ ମୁହୂର୍ତ୍ତ ଥିଲା।",
        "opinions|3:1|3|p2": "ସେହି ପରୀକ୍ଷାରେ ଫେଲ ହେବା ଏକ ମୋଡ଼ ଥିଲା; ତା'ପରେ ମୁଁ ମନଦେଇ ପଢ଼ିବା ଆରମ୍ଭ କଲି।",
        "opinions|3:1|3|p3": "ଆମ ହଷ୍ଟେଲ ୱାର୍ଡେନ ଆମର ସବୁ ଦୁଷ୍ଟାମି ଜାଣିଥିଲେ, କିନ୍ତୁ ନ ଦେଖିଲା ପରି ଅଭିନୟ କରୁଥିଲେ।",
        "opinions|3:1|3|p4": "ମୋ ପ୍ରିୟ ଶିକ୍ଷକଙ୍କ ସ୍ମୃତିଚିହ୍ନ ଭାବେ ମୁଁ ଏହି ପୁରୁଣା ଫାଉଣ୍ଟେନ ପେନଟି ରଖିଛି।",
        "opinions|3:1|4|title": "କୋଡ଼ଗୁରେ ବର୍ଷାର ସନ୍ଧ୍ୟା",
        "opinions|3:1|4|text": "ଶ୍ରେୟା କୋଡ଼ଗୁର ଏକ ଛୋଟ ଗାଁରେ ବଡ଼ ହୋଇଥିଲେ, ଯେଉଁଠି ତାଙ୍କ ପରିବାର ଆଗେ କଫି ଚାଷ କରୁଥିଲେ। ତାଙ୍କ ପିଲାଦିନର ଅଧିକାଂଶ କଥା ତାଙ୍କୁ କେବଳ ଅସ୍ପଷ୍ଟ ଭାବେ ମନେ ଅଛି, କିନ୍ତୁ ଗୋଟିଏ ଦିନ ଏବେ ବି ତାଙ୍କ ମନରେ ଜୀବନ୍ତ। ସେ ଦଶ ବର୍ଷର ଥିବା ବେଳେ ପ୍ରବଳ ବର୍ଷାରେ ନଦୀରେ ବନ୍ୟା ଆସିଲା, ଆଉ ସ୍କୁଲ ବସ ପୋଲ ପାର ହୋଇପାରିଲା ନାହିଁ। ପିଲାମାନେ ଥଣ୍ଡାରେ ଘଣ୍ଟା ଘଣ୍ଟା ଅପେକ୍ଷା କଲେ, ଶେଷରେ ପୋନପ୍ପା ନାମରେ ଜଣେ ଚାଷୀ ତାଙ୍କ ଟ୍ରାକ୍ଟର ନେଇ ଆସିଲେ। ସେ ଥରକେ ଦୁଇ ତିନିଜଣ କରି ସବୁ ତିରିଶ ପିଲାଙ୍କୁ ପାଣି ପାର କରାଇଲେ। ସେ ଦେଇଥିବା ଛୋଟ ତଉଲିଆଟି ଶ୍ରେୟା ଏବେ ବି ସ୍ମୃତିଚିହ୍ନ ଭାବେ ରଖିଛନ୍ତି। ଯେତେବେଳେ ଜୋରରେ ବର୍ଷା ହୁଏ, ତାଙ୍କୁ ହଠାତ ସେହି ସନ୍ଧ୍ୟା ମନେପଡ଼ିଯାଏ। ତାଙ୍କ ପାଇଁ ଏହା ଜୀବନର ମୋଡ଼ ଥିଲା: ସେହି ଦିନ ସେ ସ୍ଥିର କଲେ ଯେ ସେ ମଧ୍ୟ ଲୋକଙ୍କୁ ସାହାଯ୍ୟ କରି ଜୀବନ କଟାଇବେ।",
        "opinions|3:1|4|q0": "ସ୍କୁଲ ବସ କାହିଁକି ପିଲାଙ୍କୁ ଘରକୁ ନେଇପାରିଲା ନାହିଁ?",
        "opinions|3:1|4|q0o0": "ନଦୀରେ ବନ୍ୟା ଆସିଲା ଆଉ ବସ ପୋଲ ପାର ହୋଇପାରିଲା ନାହିଁ",
        "opinions|3:1|4|q0o1": "ବସ ଖରାପ ହୋଇଗଲା",
        "opinions|3:1|4|q0o2": "ଡ୍ରାଇଭର ଅସୁସ୍ଥ ଥିଲେ",
        "opinions|3:1|4|q0o3": "ରାସ୍ତାରେ ଗଛ ପଡ଼ିଗଲା",
        "opinions|3:1|4|q1": "ପିଲାମାନେ କିପରି ପାଣି ପାର ହେଲେ?",
        "opinions|3:1|4|q1o0": "ଜଣେ ଚାଷୀ ତାଙ୍କ ଟ୍ରାକ୍ଟରରେ ସେମାନଙ୍କୁ ପାର କରାଇଲେ",
        "opinions|3:1|4|q1o1": "ସେମାନେ ପୋଲ ଉପରେ ଚାଲି ପାର ହେଲେ",
        "opinions|3:1|4|q1o2": "ସହରରୁ ଏକ ଡଙ୍ଗା ଆସିଲା",
        "opinions|3:1|4|q1o3": "ସେମାନଙ୍କ ବାପାମା ସେମାନଙ୍କୁ କାନ୍ଧରେ ନେଲେ",
        "opinions|3:1|4|q2": "ଶ୍ରେୟା ସ୍ମୃତିଚିହ୍ନ ଭାବେ କ'ଣ ରଖିଛନ୍ତି?",
        "opinions|3:1|4|q2o0": "ଏକ ଛୋଟ ତଉଲିଆ",
