        "opinions|3:1|4|q2o3": "ଏକ ଫଟୋ",
        "opinions|3:1|5|title": "ଜେଜେବାପାଙ୍କ ସ୍କୁଲ ଦିନ",
        "opinions|3:1|5|scenario": "ଅନନ୍ୟା ଏକ କ୍ଲାସ ପ୍ରୋଜେକ୍ଟ ପାଇଁ ମାଣ୍ଡ୍ୟାରେ ତାଙ୍କ ଜେଜେବାପା ନାରାୟଣଙ୍କ ସହ ତାଙ୍କ ସ୍କୁଲ ଦିନ ବିଷୟରେ କଥା ହୁଅନ୍ତି।",
        "opinions|3:1|5|l0": "ଜେଜେ, ମୋ ପ୍ରୋଜେକ୍ଟ ପାଇଁ, ତୁମେ ଛୋଟ ଥିବା ବେଳେ ସ୍କୁଲ କେମିତି ଥିଲା କହିବ କି?",
        "opinions|3:1|5|l1": "ଓହୋ, ସେ ଅଲଗା ସମୟ ଥିଲା। ଆମେ ପ୍ରତିଦିନ ଚାରି କିଲୋମିଟର ଚାଲି ସ୍କୁଲ ଯାଉଥିଲୁ।",
        "opinions|3:1|5|l2": "ଚାରି କିଲୋମିଟର! ତୁମମାନଙ୍କ ପାଖରେ ବସ କି ସାଇକେଲ ନ ଥିଲା?",
        "opinions|3:1|5|l3": "ଆମ ଗାଁରେ କାହା ପାଖରେ ସାଇକେଲ ନ ଥିଲା। ଆମେ ଖାଲି ପାଦରେ ଚାଲୁଥିଲୁ ଆଉ ବାଟରେ ଗୀତ ଗାଉଥିଲୁ।",
        "opinions|3:1|5|l4": "ସେ ଦିନର ତୁମର ସବୁଠାରୁ ଜୀବନ୍ତ ସ୍ମୃତି କ'ଣ?",
        "opinions|3:1|5|l5": "ଯେଉଁ ଦିନ ହେଡମାଷ୍ଟର ମୋତେ ତାଙ୍କ ଗଛରୁ ଆମ୍ବ ଚୋରି କରୁଥିବା ଧରିଲେ। ତାଙ୍କ ମୁହଁ ମୁଁ ଏବେ ବି ଦେଖିପାରୁଛି!",
        "opinions|3:1|5|l6": "ଜେଜେ, ତୁମେ ଏମିତି ଦୁଷ୍ଟାମି କରୁଥିଲ ବୋଲି ମୁଁ ଜାଣି ନ ଥିଲି! ତା'ପରେ କ'ଣ ହେଲା?",
        "opinions|3:1|5|l7": "ସେ ମୋତେ ପୁରା ଗୋଟିଏ ମାସ ତାଙ୍କ ବଗିଚାରେ ପାଣି ଦେବାକୁ କହିଲେ। ସତ କହିବାକୁ ଗଲେ, ତାହା ଜୀବନର ମୋଡ଼ ଥିଲା; ମୋତେ ଗଛଲତା ପ୍ରତି ଭଲପାଇବା ହୋଇଗଲା।",
        "opinions|3:1|5|l8": "ସେ ଦିନଗୁଡ଼ିକ ପାଇଁ ତୁମ ମନ କେବେ ଟାଣେ କି?",
        "opinions|3:1|5|l9": "ବହୁତ ଥର। ଜୀବନ କଷ୍ଟକର ଥିଲା, କିନ୍ତୁ ଅଳ୍ପରେ ଆମେ ଖୁସି ଥିଲୁ।",
        "opinions|3:1|5|q0": "ଜେଜେ କିପରି ସ୍କୁଲ ଯାଉଥିଲେ?",
        "opinions|3:1|5|q0o0": "ସେ ଚାରି କିଲୋମିଟର ଚାଲୁଥିଲେ",
