        "opinions|5:1|5|q0o1": "ଆକାଶ ତାଙ୍କ ଜନ୍ମଦିନ ଭୁଲିଯାଇଥିଲେ",
        "opinions|5:1|5|q0o2": "ଆକାଶ ତାଙ୍କ ଗୁପ୍ତ କଥା କହିଦେଇଥିଲେ",
        "opinions|5:1|5|q0o3": "ଆକାଶ ତାଙ୍କ ନୋଟ ହଜାଇଦେଇଥିଲେ",
        "opinions|5:1|5|q1": "ଆକାଶ କାହିଁକି ଆସିପାରି ନ ଥିଲେ?",
