        "opinions|5:1|5|q2": "ଆକାଶ କାହିଁକି ସ୍ମିତାଙ୍କୁ ଫୋନ କଲେ ନାହିଁ?",
        "opinions|5:1|5|q2o0": "ତାଙ୍କ ଫୋନର ବ୍ୟାଟେରି ସରିଗଲା",
        "opinions|5:1|5|q2o1": "ସେ ତାଙ୍କ ଫୋନ ହଜାଇଦେଲେ",
