        "opinions|6:1|0|w2": "ମୁଁ ତୁମ ଜାଗାରେ ଥିଲେ",
        "opinions|6:1|0|w3": "ତୁମେ ବରଂ",
        "opinions|6:1|0|w4": "କାହିଁକି ନୁହେଁ",
        "opinions|6:1|0|w5": "ଅଭିଜ୍ଞତାର ନିୟମ",
        "opinions|6:1|1|p0": "ପରାମର୍ଶ ପାଇଁ ଧନ୍ୟବାଦ; ମୁଁ ଏହି ସପ୍ତାହରେ ଚେଷ୍ଟା କରିବି।",
        "opinions|6:1|1|p1": "ଛୋଟ ପରାମର୍ଶଟିଏ: ଯେଉଁ କାଗଜ ପଢ଼ିନାହଁ, ସେଥିରେ କେବେ ଦସ୍ତଖତ କର ନାହିଁ।",
        "opinions|6:1|1|p2": "ମୁଁ ତୁମ ଜାଗାରେ ଥିଲେ, କଥା ବଢ଼ିବା ଆଗରୁ ତାଙ୍କୁ କ୍ଷମା ମାଗିଥାନ୍ତି।",
        "opinions|6:1|1|p3": "ତୁମେ ବରଂ ଏବେ ବାହାରିଯାଅ, ନଚେତ ହାସନର ଶେଷ ବସ ଛୁଟିଯିବ।",
        "opinions|6:1|1|p4": "ତୁମେ ମୋ ସହ କବନ ପାର୍କର ସକାଳ ଚାଲିବା ଦଳରେ କାହିଁକି ଯୋଗ ଦେଉନାହଁ?",
