        "opinions|6:1|2|w1": "ଦୋଳାୟମାନ",
        "opinions|6:1|2|w2": "ପରାମର୍ଶ ସାଥୀ",
        "opinions|6:1|2|w3": "ଧ୍ୟାନ ଦେବା",
        "opinions|6:1|2|w4": "ଭଲ ଭାବେ ଭାବିବା",
        "opinions|6:1|2|w5": "ପୁରା ବିଶ୍ୱାସ ନ କରି",
        "opinions|6:1|3|p0": "ମୁଁ ପ୍ରକୃତରେ ଦ୍ୱନ୍ଦ୍ୱରେ ଅଛି: ପୁଣେର ଚାକିରି ନେବି ନା ଘରେ ରହିବି?",
        "opinions|6:1|3|p1": "ସେ କଳା ପଢ଼ିବା ଆଉ ପାରିବାରିକ ବ୍ୟବସାୟରେ ଯୋଗ ଦେବା ମଧ୍ୟରେ ଦୋଳାୟମାନ।",
        "opinions|6:1|3|p2": "ଯେତେବେଳେ ମୋତେ କିଛି ବଡ଼ ନିଷ୍ପତ୍ତି ନେବାକୁ ହୁଏ, ମୋ ମାମୁଁ ଜଣେ ଚମତ୍କାର ପରାମର୍ଶ ସାଥୀ।",
        "opinions|6:1|3|p3": "ସେ ଡାକ୍ତରଙ୍କ ଚେତାବନୀ ଉପରେ ଧ୍ୟାନ ଦେଲେ ନାହିଁ ଏବଂ ପୁଣି ଅସୁସ୍ଥ ହୋଇପଡ଼ିଲେ।",
        "opinions|6:1|3|p4": "ଭଲ ଭାବେ ଭାବି ଦେଖ, ଆଉ ଅନଲାଇନ ରିଭ୍ୟୁକୁ ପୁରା ବିଶ୍ୱାସ କର ନାହିଁ।",
        "opinions|6:1|4|title": "ଆଈଙ୍କ ପରାମର୍ଶ",
        "opinions|6:1|4|text": "ଉଡୁପିର ସ୍ନେହାଙ୍କ ପାଖରେ ଏକ ଦ୍ୱନ୍ଦ୍ୱ ଥିଲା: ଅହମଦାବାଦର ଏକ ଡିଜାଇନ କଲେଜରେ ତାଙ୍କୁ ସିଟ ମିଳିଥିଲା, କିନ୍ତୁ ତାଙ୍କ ବାପାମା ଚାହୁଁଥିଲେ ସେ ଘର ପାଖରେ ପଢ଼ନ୍ତୁ। ସେ ନିଜ ସ୍ୱପ୍ନ ଆଉ ପରିବାର ମଧ୍ୟରେ ଦୋଳାୟମାନ ଥିଲେ, ତେଣୁ ସେ ତାଙ୍କ ଆଈଙ୍କ ପାଖକୁ ଗଲେ, ଯିଏ ସବୁବେଳେ ତାଙ୍କ ପରାମର୍ଶ ସାଥୀ ଥିଲେ। ଆଈ ଚୁପଚାପ ଶୁଣିଲେ ଏବଂ ତା'ପରେ କହିଲେ, 'ମୁଁ ତୁମ ଜାଗାରେ ଥିଲେ, ତରବରରେ ନିଷ୍ପତ୍ତି ନେଇ ନ ଥାନ୍ତି; କିଛି ଦିନ ଭଲ ଭାବେ ଭାବି ଦେଖ।' ସମ୍ପର୍କୀୟଙ୍କ ମନ୍ତବ୍ୟ ବିଷୟରେ ସେ ସ୍ନେହାଙ୍କୁ ଏକ ଛୋଟ ପରାମର୍ଶ ମଧ୍ୟ ଦେଲେ: ସେଗୁଡ଼ିକୁ ପୁରା ବିଶ୍ୱାସ କର ନାହିଁ। 'ମୋ ଅଭିଜ୍ଞତାର ନିୟମ ସରଳ,' ଆଈ କହିଲେ, 'ସେହି ବାଟ ବାଛ, ଯାହା ପାଇଁ ଷାଠିଏ ବର୍ଷରେ ଆପଶୋଷ ହେବ ନାହିଁ।' ତା'ପରେ ସେ ଏକ ପରାମର୍ଶ ଦେଲେ: 'ତୁମ ବାପାମାଙ୍କୁ କଲେଜ ୱେବସାଇଟ ଆଉ ତୁମ ପୋର୍ଟଫୋଲିଓ କାହିଁକି ଦେଖାଉନାହଁ?' ସ୍ନେହା ତାଙ୍କ ପରାମର୍ଶ ଉପରେ ଧ୍ୟାନ ଦେଲେ, ଆଉ ତାଙ୍କ କାମ ଦେଖି ବାପାମା ରାଜି ହୋଇଗଲେ। ଆଜି ସେ ପ୍ରତି ରବିବାର ଆଈଙ୍କୁ ଫୋନ କରି ତାଙ୍କ କ୍ଲାସ ବିଷୟରେ ସବୁ କହନ୍ତି।",
