        "opinions|6:1|5|scenario": "ଧାରୱାଡ଼ର ପ୍ରଥମ ବର୍ଷ ଛାତ୍ର ଦୀପକ ତାଙ୍କ ହଷ୍ଟେଲ ରୁମମେଟ ବିଷୟରେ ପରାମର୍ଶ ପାଇଁ ତାଙ୍କ ବଡ଼ ମାମୁଁ ଝିଅ ଶାଳିନୀଙ୍କୁ ଫୋନ କରନ୍ତି।",
        "opinions|6:1|5|l0": "ଶାଳିନୀ ଅପା, ଗୋଟିଏ କଥାରେ ତୁମ ପରାମର୍ଶ ମାଗିପାରେ କି? ଆଉ କାହା ସହ କଥା ହେବି ଜାଣିପାରୁନି।",
