        "opinions|6:1|5|l3": "ଏହା ତ ବହୁତ କ୍ଲାନ୍ତିକର। ଏହା ତୁମ ଉପରେ କି ପ୍ରଭାବ ପକାଉଛି, ତାକୁ କହିଛ କି?",
        "opinions|6:1|5|l4": "ସେମିତି ନୁହେଁ। ମୋତେ ଡର ଲାଗୁଛି ଯେ ଝଗଡ଼ା ହେବ, ଆଉ ଆମକୁ ସାରା ବର୍ଷ ଏକାଠି ରହିବାକୁ ପଡ଼ିବ।",
        "opinions|6:1|5|l5": "ମୁଁ ତୁମ ଜାଗାରେ ଥିଲେ, ଯେତେବେଳେ ଦୁହେଁ ଆରାମରେ ଥାଅ, ସେତେବେଳେ ତା' ସହ ଶାନ୍ତ ଭାବେ କଥା ହୁଅନ୍ତି।",
        "opinions|6:1|5|l6": "ଏହା ଭଲ ପରାମର୍ଶ। କିନ୍ତୁ ପ୍ରକୃତରେ କ'ଣ କହିବି?",
        "opinions|6:1|5|l7": "ଅଭିଜ୍ଞତାର ଏକ ଭଲ ନିୟମ ହେଉଛି, ତା' ଦୋଷ ନୁହେଁ, ତୁମ ସମସ୍ୟା ବିଷୟରେ କହିବା। ଏଗାରଟା ପରେ ହେଡଫୋନ ବ୍ୟବହାର କରିବାକୁ କାହିଁକି କହୁନାହଁ?",
        "opinions|6:1|5|l8": "ଏହା ଠିକ ଲାଗୁଛି। ମୁଁ ଭଲ ଭାବେ ଭାବିବି ଏବଂ ଏହି ସପ୍ତାହାନ୍ତରେ ତା' ସହ କଥା ହେବି।",
