        "services|1:1|4|title": "ରାତିରେ ଔଷଧ ଦୋକାନରେ",
        "services|1:1|4|text": "ମହୀଶୂରରେ ଦିନେ ରାତି ଦଶଟାରେ ମୀରାଙ୍କ ସାନ ଭାଇ ରୋହନ ପ୍ରବଳ ଜ୍ୱର ନେଇ ଉଠିଲା। ସେମାନଙ୍କ ପାରିବାରିକ ଡାକ୍ତର ସହର ବାହାରେ ଥିଲେ, ତେଣୁ ମୀରା ତାଙ୍କୁ ଫୋନ କରି ପରାମର୍ଶ ନେଲେ। ଡାକ୍ତର କହିଲେ ସକାଳ ପର୍ଯ୍ୟନ୍ତ ଜ୍ୱର ସିରପ ଯଥେଷ୍ଟ ହେବ। ମୀରା ବସ ଷ୍ଟାଣ୍ଡ ପାଖରେ ରାତିସାରା ଖୋଲା ରହୁଥିବା ଏକ ଔଷଧ ଦୋକାନ ପାଇଲେ। ସେ ଫାର୍ମାସିଷ୍ଟଙ୍କୁ କହିଲେ ଯେ ରୋହନର ବୟସ ଆଠ ବର୍ଷ ଏବଂ ତା'ର ଗୋଟିଏ ଆଣ୍ଟିବାୟୋଟିକରେ ଆଲର୍ଜି ଅଛି। ଫାର୍ମାସିଷ୍ଟ ମିଆଦ ତାରିଖ ଦେଖିଲେ, ଡବା ଉପରେ ମାତ୍ରା ଲେଖିଦେଲେ ଏବଂ ସାବଧାନ କଲେ ଯେ ସିରପ ଖାଇଲେ ରୋହନକୁ ନିଦୁଆ ଲାଗିପାରେ। ସକାଳ ସୁଦ୍ଧା ରୋହନର ଜ୍ୱର କମିଗଲା ଏବଂ ସେ ଦୋସା ମାଗୁଥିଲା।",
