        "services|1:1|5|scenario": "କିରଣଙ୍କୁ ଖୁବ ଥଣ୍ଡା ଲାଗିଛି, ଆଉ ସେ ହୁବ୍ବଳିର ଫାର୍ମାସିଷ୍ଟ ଲତାଙ୍କୁ ପରାମର୍ଶ ମାଗନ୍ତି।",
        "services|1:1|5|l0": "ଶୁଭ ସନ୍ଧ୍ୟା। କହନ୍ତୁ, କି ସାହାଯ୍ୟ କରିବି?",
