        "services|1:1|5|l6": "ଟିକେ ନିଦୁଆ ଲାଗିପାରେ, ତେଣୁ ରାତିର ଡୋଜ ପରେ ଦୟାକରି ଗାଡ଼ି ଚଲାନ୍ତୁ ନାହିଁ।",
