        "services|2:1|1|p1": "ଦୟାକରି ଶୀଘ୍ର ଆମ୍ବୁଲାନ୍ସ ପଠାନ୍ତୁ; ଜଣେ ଲୋକ ରାସ୍ତାରେ ପଡ଼ିଛନ୍ତି।",
        "services|2:1|1|p2": "ଜରୁରୀ ଅବସ୍ଥାରେ 112 ହେଲ୍ପଲାଇନକୁ ଫୋନ କରନ୍ତୁ ଏବଂ ଧୀରେ ଓ ସ୍ପଷ୍ଟ ଭାବେ କୁହନ୍ତୁ।",
        "services|2:1|1|p3": "ଦମକଳ ବାଟରେ ଅଛି, ତେଣୁ ଦୟାକରି ଏବେ ବିଲ୍ଡିଂରୁ ବାହାରିଯାଆନ୍ତୁ।",
        "services|2:1|1|p4": "ସବୁଠାରୁ ପାଖ ଚିହ୍ନା ଜାଗା ହେଉଛି ପେଟ୍ରୋଲ ପମ୍ପ ସାମ୍ନାରେ ଥିବା ବଡ଼ ମନ୍ଦିର।",
