        "services|2:1|3|p0": "ଦୁଇଜଣ ଲୋକ ଆହତ, ଆଉ ସେମାନଙ୍କ ମଧ୍ୟରୁ ଜଣେ ଅଚେତ ଅଛନ୍ତି।",
        "services|2:1|3|p1": "ରକ୍ତ ବନ୍ଦ କରିବାକୁ ଘା ଉପରେ ଏକ ସଫା କପଡ଼ା ଚାପି ଧରନ୍ତୁ।",
        "services|2:1|3|p2": "ଆପଣ ପ୍ରାଥମିକ ଚିକିତ୍ସା ଜାଣନ୍ତି କି, ନା ଆମେ ଆମ୍ବୁଲାନ୍ସ ପାଇଁ ଅପେକ୍ଷା କରିବା?",
        "services|2:1|3|p3": "ଷ୍ଟେସନରେ ମୋ ବ୍ୟାଗ ଚୋରି ହୋଇଗଲା, ଆଉ ମୋତେ ଚୋରି ବିଷୟରେ ରିପୋର୍ଟ କରିବାକୁ ପଡ଼ିବ।",
        "services|2:1|3|p4": "ଘାବରାନ୍ତୁ ନାହିଁ; ଲମ୍ବା ନିଶ୍ୱାସ ନିଅନ୍ତୁ ଏବଂ ମୋତେ ଆପଣଙ୍କ ଠିକଣା କୁହନ୍ତୁ।",
        "services|2:1|4|title": "ହାଇୱେରେ ସାହାଯ୍ୟ",
        "services|2:1|4|text": "ରବି ମଙ୍ଗଳୁରୁରୁ ଉଡୁପି ଗାଡ଼ି ଚଲାଇ ଯାଉଥିଲେ, ସେତେବେଳେ ସେ ହାଇୱେ କଡ଼ରେ ଗୋଟିଏ ବାଇକ ପଡ଼ିଥିବା ଦେଖିଲେ। ତା' ପାଖରେ ଜଣେ ଯୁବକ ବସିଥିଲେ, ଆଉ ତାଙ୍କ ହାତରୁ ବହୁତ ରକ୍ତ ବାହାରୁଥିଲା। ରବି ତାଙ୍କ କାର ରଖିଲେ ଏବଂ ନିଜକୁ କହିଲେ, ଘାବରାଅ ନାହିଁ। ସେ 108କୁ ଫୋନ କରି କହିଲେ, 'ମୁଁ ଏକ ଦୁର୍ଘଟଣା ବିଷୟରେ ଜଣାଇବାକୁ ଚାହେଁ; ଜଣେ ଆହତ ହୋଇଛନ୍ତି।' ଅପରେଟର ଠିକ ଜାଗା ପଚାରିଲେ, ତେଣୁ ରବି ସବୁଠାରୁ ପାଖ ଚିହ୍ନା ଜାଗା, ସୁରତକଲ ଲାଇଟହାଉସର ନାଁ କହିଲେ। ଅପେକ୍ଷା କରିବା ବେଳେ ରବି ଘା ଉପରେ ଏକ ସଫା ତଉଲିଆ ଚାପି ପ୍ରାଥମିକ ଚିକିତ୍ସା ଦେଲେ। ପନ୍ଦର ମିନିଟରେ ଆମ୍ବୁଲାନ୍ସ ପହଞ୍ଚିଲା, ଆଉ ପରେ ସେହି ଯୁବକ ଶାନ୍ତ ରହିଥିବାରୁ ରବିଙ୍କୁ ଧନ୍ୟବାଦ ଦେଲେ।",
