        "services|2:1|5|scenario": "ନନ୍ଦିନୀ ପୁଣେରେ ତାଙ୍କ ଗଳିର ଗୋଟିଏ ଘରରୁ ଧୂଆଁ ବାହାରୁଥିବା ଦେଖନ୍ତି ଏବଂ 112 ଜରୁରୀ ହେଲ୍ପଲାଇନକୁ ଫୋନ କରନ୍ତି। ସୁରେଶ ଫୋନ ଉଠାନ୍ତି।",
        "services|2:1|5|l0": "112 ଜରୁରୀ ହେଲ୍ପଲାଇନ। କି ଜରୁରୀ ଅବସ୍ଥା?",
        "services|2:1|5|l1": "ମୋ ଗଳିର ଗୋଟିଏ ଘରେ ନିଆଁ ଲାଗିଛି। ଉପର ମହଲାର ଝରକାରୁ ଘନ ଧୂଆଁ ବାହାରୁଥିବା ଦେଖିପାରୁଛି।",
        "services|2:1|5|l2": "ଦୟାକରି ଶାନ୍ତ ରୁହନ୍ତୁ, ମାଡାମ। ଘର ଭିତରେ ଏବେ ବି କେହି ଅଛନ୍ତି କି?",
        "services|2:1|5|l3": "ମୁଁ ନିଶ୍ଚିତ ନୁହେଁ। ସେଠି ଜଣେ ବୁଢ଼ା ଦମ୍ପତି ରହନ୍ତି, ଆଉ ମୁଁ ସେମାନଙ୍କୁ ବାହାରେ ଦେଖିପାରୁନାହିଁ।",
