        "services|2:1|5|l5": "ଘର ନମ୍ବର 14, ଶାନ୍ତି ନଗର, କୋଥରୁଡ଼। ଚିହ୍ନା ଜାଗା ହେଉଛି କୋଣରେ ଥିବା ନୀଳ ପାଣି ଟାଙ୍କି।",
        "services|2:1|5|l6": "ଧନ୍ୟବାଦ। ଦୟାକରି ଭିତରକୁ ଯିବେ ନାହିଁ, ଆଉ ଅନ୍ୟ ଲୋକଙ୍କୁ ଧୂଆଁଠାରୁ ଦୂରରେ ରଖନ୍ତୁ।",
        "services|2:1|5|l7": "ଠିକ ଅଛି। ଓହୋ, ଜଣେ ପଡ଼ୋଶୀ କହୁଛନ୍ତି ଦମ୍ପତି ମନ୍ଦିରକୁ ଯାଇଛନ୍ତି, ତେଣୁ ଘର ଖାଲି ଅଛି।",
        "services|2:1|5|l8": "ଏହା ଭଲ ଖବର। ଦମକଳ ପ୍ରାୟ ଦଶ ମିନିଟରେ ଆପଣଙ୍କ ପାଖରେ ପହଞ୍ଚିବ। ଦୟାକରି ଫୋନ ରଖନ୍ତୁ ନାହିଁ।",
        "services|2:1|5|l9": "ବହୁତ ଧନ୍ୟବାଦ। ମୁଁ ଏବେଠୁ ସାଇରନ ଶୁଣିପାରୁଛି।",
