        "services|3:1|1|p0": "ରୋଷେଇଘରର କଳରୁ ରାତିସାରା ପାଣି ଟପ ଟପ ଝରୁଛି; ଆଜି ଜଣେ ପ୍ଲମ୍ବର ପଠାଇପାରିବେ କି?",
        "services|3:1|1|p1": "ବାଥରୁମ ସିଙ୍କ ତଳେ ଲିକେଜ ଅଛି, ଆଉ ଚଟାଣ ସବୁବେଳେ ଓଦା ରହୁଛି।",
        "services|3:1|1|p2": "ଯେତେଥର ମୁଁ ଗିଜର ଅନ କରୁଛି, ଫ୍ୟୁଜ ଉଡ଼ିଯାଉଛି।",
        "services|3:1|1|p3": "ଇଲେକଟ୍ରିସିଆନ କହୁଛନ୍ତି ଏହି ଫ୍ଲାଟର ପୁରୁଣା ୱାୟାରିଂ ସୁରକ୍ଷିତ ନୁହେଁ।",
        "services|3:1|1|p4": "କୌଣସି ତାର ଛୁଇଁବା ଆଗରୁ ଦୟାକରି ମେନ ସୁଇଚ ବନ୍ଦ କରନ୍ତୁ।",
