        "services|3:1|3|p0": "ଆମ ୱାସିଂ ମେସିନରେ ତ୍ରୁଟି ଅଛି; ପ୍ରତିଥର ଧୋଇବା ମଝିରେ ଏହା ବନ୍ଦ ହୋଇଯାଉଛି।",
        "services|3:1|3|p1": "ମୁଁ କାମକୁ ବାହାରିବା ଆଗରୁ, କାଲି ସକାଳେ ଟେକ୍ନିସିଆନ ଆସିପାରିବେ କି?",
        "services|3:1|3|p2": "ଆରମ୍ଭ କରିବା ଆଗରୁ, ମୋଟ ଖର୍ଚ୍ଚର ଏକ ଆନୁମାନିକ ହିସାବ ଦେଇପାରିବେ କି?",
        "services|3:1|3|p3": "ବେଙ୍ଗାଲୁରୁରୁ ସ୍ପେୟାର ପାର୍ଟ ଆସିବାକୁ ତିନି ଦିନ ଲାଗିବ।",
        "services|3:1|3|p4": "ଯେକୌଣସି ବଡ଼ ଘରୋଇ ଯନ୍ତ୍ର ପାଇଁ ପ୍ରତି ଭିଜିଟରେ ସର୍ଭିସ ଚାର୍ଜ ତିନି ଶହ ଟଙ୍କା।",
        "services|3:1|4|title": "ଥଣ୍ଡା ନ କରୁଥିବା ଫ୍ରିଜ",
        "services|3:1|4|text": "ମେ ମାସର ଗରମ ସପ୍ତାହରେ କଲବୁର୍ଗିରେ କୁଲକର୍ଣ୍ଣୀ ପରିବାରର ଫ୍ରିଜ ହଠାତ ଥଣ୍ଡା କରିବା ବନ୍ଦ କରିଦେଲା। ସୁନୀତା କମ୍ପାନୀର ସର୍ଭିସ ସେଣ୍ଟରକୁ ଫୋନ କରି ତ୍ରୁଟିଟି ସ୍ପଷ୍ଟ ଭାବେ ବୁଝାଇଲେ: ଲାଇଟ ଜଳୁଛି, କିନ୍ତୁ ଭିତରଟା ଗରମ। ପରଦିନ ଅପରାହ୍ନରେ ଜଣେ ଟେକ୍ନିସିଆନ ଆସି ଯନ୍ତ୍ରଟି ଭଲ ଭାବେ ଯାଞ୍ଚ କଲେ। ସେ କହିଲେ ଯେ କୁଲିଂ ସିଷ୍ଟମର ଗୋଟିଏ ସ୍ପେୟାର ପାର୍ଟ ଖରାପ ହୋଇଯାଇଛି ଏବଂ ତାହା ବଦଳାଇବାକୁ ପଡ଼ିବ। ସେ କାମ ଆରମ୍ଭ କରିବା ଆଗରୁ ସୁନୀତା ଭଦ୍ର ଭାବେ ଆନୁମାନିକ ଖର୍ଚ୍ଚ ପଚାରିଲେ, ଆଉ ସେ କହିଲେ ସର୍ଭିସ ଚାର୍ଜ ସହିତ ମୋଟ ପ୍ରାୟ ଦୁଇ ହଜାର ଟଙ୍କା ହେବ। ଦୁଇ ଦିନ ପରେ ହୁବ୍ବଳିରୁ ପାର୍ଟଟି ଆସିଲା, ଏବଂ ଟେକ୍ନିସିଆନ ଘଣ୍ଟାଏ ଭିତରେ ଫ୍ରିଜ ଠିକ କରିଦେଲେ। ସେଦିନ ସନ୍ଧ୍ୟାରେ ଫ୍ରିଜ ପୁଣି ଥଣ୍ଡା ହେଲା, ଆଉ ପରିବାର ଶେଷରେ କ୍ଷୀର ଓ ଦହି ରଖିପାରିଲେ।",
