        "services|3:1|5|l0": "ସୁପ୍ରଭାତ, କ୍ୱିକଫିକ୍ସ ହୋମ ସର୍ଭିସେସ। ମୁଁ ଆଶା କହୁଛି। କି ସାହାଯ୍ୟ କରିପାରିବି?",
        "services|3:1|5|l1": "ନମସ୍କାର, ମୁଁ ଗୋଟିଏ ବିଜୁଳି ସମସ୍ୟା ବିଷୟରେ ଫୋନ କରୁଛି। ମୋ ଫ୍ଲାଟରେ ବାରମ୍ବାର ଫ୍ୟୁଜ ଉଡ଼ିଯାଉଛି, ବିଶେଷକରି ସନ୍ଧ୍ୟାରେ।",
        "services|3:1|5|l2": "ଆଚ୍ଛା। କୌଣସି ନିର୍ଦ୍ଦିଷ୍ଟ ଯନ୍ତ୍ର ଅନ କଲେ ଏମିତି ହୁଏ କି?",
        "services|3:1|5|l3": "ମୋତେ ସେମିତି ଲାଗୁଛି। ଗିଜର ଆଉ ଇସ୍ତ୍ରି ଏକାସାଙ୍ଗରେ ଚାଲିଲେ ସାଧାରଣତଃ ଏମିତି ହୁଏ।",
        "services|3:1|5|l4": "ୱାୟାରିଂରେ ତ୍ରୁଟି ଥାଇପାରେ। ମୁଁ ଯାଞ୍ଚ କରିବାକୁ ଜଣେ ଇଲେକଟ୍ରିସିଆନ ପଠାଇପାରିବି। ଆପଣଙ୍କୁ କେବେ ସୁବିଧା ହେବ?",
        "services|3:1|5|l5": "ଆଜି କାହାକୁ ପଠାଇପାରିବେ କି? ମୁଁ ଛଅଟା ପର୍ଯ୍ୟନ୍ତ ଘରୁ କାମ କରୁଛି।",
        "services|3:1|5|l6": "ଆମ ଇଲେକଟ୍ରିସିଆନ ମହେଶ ଚାରିଟାରେ ଆସିପାରିବେ। ଭିଜିଟ ପାଇଁ ସର୍ଭିସ ଚାର୍ଜ ଦୁଇ ଶହ ପଚାଶ ଟଙ୍କା।",
        "services|3:1|5|l7": "ଠିକ ଅଛି। ମରାମତି ଆରମ୍ଭ କରିବା ଆଗରୁ ସେ ମୋତେ ଆନୁମାନିକ ଖର୍ଚ୍ଚ କହିବେ ତ?",
        "services|3:1|5|l8": "ହଁ, ସେ ସବୁବେଳେ ପ୍ରଥମେ ଖର୍ଚ୍ଚ ବୁଝାନ୍ତି। ଦୟାକରି ହ୍ୱାଟସଆପରେ ଆପଣଙ୍କ ଠିକଣା ପଠାନ୍ତୁ।",
