        "services|4:1|1|p0": "ଗତ ସପ୍ତାହରେ ଏଠୁ କିଣିଥିବା ଗୋଟିଏ ମିକ୍ସି ବିଷୟରେ ମୁଁ ଅଭିଯୋଗ କରିବାକୁ ଚାହେଁ।",
        "services|4:1|1|p1": "ମୋଟରଟି ତ୍ରୁଟିପୂର୍ଣ୍ଣ, ତେଣୁ ମୁଁ ରିପ୍ଲେସମେଣ୍ଟ କିମ୍ବା ପୁରା ଟଙ୍କା ଫେରସ୍ତ ଚାହେଁ।",
        "services|4:1|1|p2": "ଏଇ ରସିଦ, ଆଉ ଡବାରେ ଏବେ ବି ସବୁ ପାର୍ଟ ଅଛି।",
        "services|4:1|1|p3": "ଏହା ଏବେ ବି ୱାରେଣ୍ଟିରେ ଅଛି, ତେଣୁ ମରାମତି ମାଗଣାରେ ହେବା କଥା।",
        "services|4:1|1|p4": "ଦୁଃଖିତ, କିନ୍ତୁ ଭାଉଚର ଯଥେଷ୍ଟ ନୁହେଁ; ମୁଁ ପ୍ରକୃତରେ ଟଙ୍କା ଫେରସ୍ତ ଚାହେଁ।",
        "services|4:1|2|w0": "କଷ୍ଟମର କେୟାର",
        "services|4:1|2|w1": "ସୁପରଭାଇଜର",
        "services|4:1|2|w2": "ଉପର ଅଧିକାରୀଙ୍କୁ ପଠାଇବା",
        "services|4:1|2|w3": "କ୍ଷତିପୂରଣ",
        "services|4:1|2|w4": "ଡେଲିଭରି",
        "services|4:1|2|w5": "ଅସୁବିଧା",
        "services|4:1|3|p0": "ମୁଁ ତିନିଥର କଷ୍ଟମର କେୟାରକୁ ଫୋନ କରିସାରିଛି, ଆଉ କେହି ସମସ୍ୟାର ସମାଧାନ କରିନାହାନ୍ତି।",
        "services|4:1|3|p1": "ଏହି ବିଷୟରେ ମୁଁ ଦୟାକରି ଆପଣଙ୍କ ସୁପରଭାଇଜରଙ୍କ ସହ କଥା ହୋଇପାରିବି କି?",
        "services|4:1|3|p2": "ଶୁକ୍ରବାର ସୁଦ୍ଧା ଠିକ ନ ହେଲେ, ମୋତେ ମୋ ଅଭିଯୋଗ ଉପର ଅଧିକାରୀଙ୍କୁ ପଠାଇବାକୁ ପଡ଼ିବ।",
        "services|4:1|3|p3": "ଡେଲିଭରି ଦଶ ଦିନ ଡେରିରେ ହେଲା, ଆଉ ପାର୍ସଲଟି ନଷ୍ଟ ହୋଇଯାଇଥିଲା।",
        "services|4:1|3|p4": "ଅସୁବିଧା ପାଇଁ ଆମେ କ୍ଷମା ମାଗୁଛୁ ଏବଂ କ୍ଷତିପୂରଣ ଭାବେ ଦୁଇ ଶହ ଟଙ୍କା ଯୋଡ଼ିଦେବୁ।",
        "services|4:1|4|title": "ଭଦ୍ର କିନ୍ତୁ ଦୃଢ଼",
        "services|4:1|4|text": "ଇମରାନ ବେଳଗାଭିରେ ତାଙ୍କ ମା ପାଇଁ ଅନଲାଇନରେ ଗୋଟିଏ ଇଲେକଟ୍ରିକ କେଟଲ ଅର୍ଡର କଲେ, କିନ୍ତୁ ଡେଲିଭରି ଏକ ସପ୍ତାହ ଡେରିରେ ଆସିଲା। ମା ଯେତେବେଳେ ଏହାକୁ ଅନ କଲେ, କେଟଲରୁ ପୋଡ଼ା ଗନ୍ଧ ବାହାରିଲା ଏବଂ ଏହା କାମ କରିବା ବନ୍ଦ କରିଦେଲା। ଇମରାନ କଷ୍ଟମର କେୟାରକୁ ଫୋନ କଲେ, ଅର୍ଡର ନମ୍ବର ଦେଲେ ଏବଂ ବୁଝାଇଲେ ଯେ ଜିନିଷଟି ତ୍ରୁଟିପୂର୍ଣ୍ଣ। ପ୍ରଥମ ଏଜେଣ୍ଟ କେବଳ ଏକ ଭାଉଚର ଦେବାକୁ କହିଲେ, ତେଣୁ ଇମରାନ ଭଦ୍ର ଭାବେ ସୁପରଭାଇଜରଙ୍କ ସହ କଥା ହେବାକୁ ମାଗିଲେ। ସେ ଶାନ୍ତ କିନ୍ତୁ ଦୃଢ଼ ରହି କହିଲେ, 'ଦୁଃଖିତ, ଭାଉଚର ଯଥେଷ୍ଟ ନୁହେଁ; କେଟଲଟି ୱାରେଣ୍ଟିରେ ଅଛି, ଆଉ ମୋ ପାଖରେ ରସିଦ ଅଛି।' ସୁପରଭାଇଜର ଅସୁବିଧା ପାଇଁ କ୍ଷମା ମାଗିଲେ ଏବଂ ଦୁଇ ଦିନ ଭିତରେ ରିପ୍ଲେସମେଣ୍ଟ ପଠାଇବାକୁ ରାଜି ହେଲେ। ଡେରି ଡେଲିଭରି ପାଇଁ କ୍ଷତିପୂରଣ ଭାବେ ସେ ତାଙ୍କ ଆକାଉଣ୍ଟରେ ଏକ ଶହ ଟଙ୍କା ମଧ୍ୟ ଯୋଡ଼ିଦେଲେ।",
