        "services|4:1|4|q2o2": "ଆସନ୍ତା ମାସରେ କେଟଲ ମରାମତି କରିବା",
        "services|4:1|4|q2o3": "ତାଙ୍କ ଘରକୁ ଟେକ୍ନିସିଆନ ପଠାଇବା",
        "services|4:1|5|title": "କଷ୍ଟମର କେୟାରକୁ ଫୋନ",
        "services|4:1|5|scenario": "ଦୀପା ଭୁଲ କୁର୍ତ୍ତା ପାଇଥିବାରୁ ଏକ ଅନଲାଇନ ଦୋକାନର କଷ୍ଟମର କେୟାରକୁ ଫୋନ କରନ୍ତି। ପ୍ରକାଶ ଫୋନ ଉଠାନ୍ତି।",
        "services|4:1|5|l0": "ଶପକାର୍ଟ କଷ୍ଟମର କେୟାରକୁ ଫୋନ କରିଥିବାରୁ ଧନ୍ୟବାଦ। ମୁଁ ପ୍ରକାଶ କହୁଛି। କି ସାହାଯ୍ୟ କରିପାରିବି?",
        "services|4:1|5|l1": "ନମସ୍କାର, ପ୍ରକାଶ। ମୁଁ ଅର୍ଡର ନମ୍ବର 4582 ବିଷୟରେ ଫୋନ କରୁଛି। କାଲି ମୁଁ ଭୁଲ ଜିନିଷ ପାଇଲି।",
        "services|4:1|5|l2": "ଏହା ଶୁଣି ଦୁଃଖ ଲାଗିଲା। ଆପଣ କ'ଣ ଅର୍ଡର କରିଥିଲେ ଆଉ କ'ଣ ପାଇଲେ, କହିବେ କି?",
        "services|4:1|5|l3": "ମୁଁ ମିଡିୟମ ସାଇଜର ଗୋଟିଏ ନୀଳ ସୂତା କୁର୍ତ୍ତା ଅର୍ଡର କରିଥିଲି, କିନ୍ତୁ ଏକ୍ସଟ୍ରା ଲାର୍ଜର ଲାଲ କୁର୍ତ୍ତା ପାଇଲି।",
        "services|4:1|5|l4": "ଅସୁବିଧା ପାଇଁ କ୍ଷମା ମାଗୁଛି। ଆପଣ ରିପ୍ଲେସମେଣ୍ଟ ଚାହାଁନ୍ତି ନା ଟଙ୍କା ଫେରସ୍ତ?",
        "services|4:1|5|l5": "ଟଙ୍କା ଫେରସ୍ତ ହେଲେ ଭଲ। ଏହି ରବିବାର ଗୋଟିଏ ବାହାଘର ପାଇଁ ମୋତେ ଏହା ଦରକାର ଥିଲା, ଆଉ ନୂଆଟି ସମୟରେ ଆସିବ ନାହିଁ।",
        "services|4:1|5|l6": "ବୁଝିଲି। ଆମ ଡେଲିଭରି ପାର୍ଟନର କାଲି ଦଶଟାରୁ ଦୁଇଟା ମଧ୍ୟରେ ପାର୍ସଲ ନେଇଯିବେ।",
