        "services|5:1|2|w5": "ପ୍ରାପ୍ତି ରସିଦ",
        "services|5:1|3|p0": "ଦୟାକରି ଗୋଟିଏ ଟୋକେନ ନିଅନ୍ତୁ ଏବଂ ଆପଣଙ୍କ ନମ୍ବର ଡକା ନ ହେବା ପର୍ଯ୍ୟନ୍ତ ଅପେକ୍ଷା କରନ୍ତୁ।",
        "services|5:1|3|p1": "ଶୁଣନ୍ତୁ, ଆଧାର ଅପଡେଟ ପାଇଁ ଏହା ଠିକ ଧାଡ଼ି କି?",
        "services|5:1|3|p2": "ଅଧିକାରୀ କହିଲେ ମୋ ଆଙ୍ଗୁଠି ଛାପ ପୁଣି ସ୍କାନ କରିବାକୁ ପଡ଼ିବ।",
        "services|5:1|3|p3": "ପାସପୋର୍ଟ ପାଇଁ ପୋଲିସ ଯାଞ୍ଚରେ ସାଧାରଣତଃ ପ୍ରାୟ ଦୁଇ ସପ୍ତାହ ଲାଗେ।",
        "services|5:1|3|p4": "ଏହି ପ୍ରାପ୍ତି ରସିଦଟି ସାବଧାନରେ ରଖନ୍ତୁ; ଆବେଦନର ସ୍ଥିତି ଜାଣିବାକୁ ଏହା ଦରକାର ହେବ।",
        "services|5:1|4|title": "ଆଧାର କେନ୍ଦ୍ରରେ ଗୋଟିଏ ସକାଳ",
        "services|5:1|4|text": "ଲକ୍ଷ୍ମୀ କାମ ପାଇଁ ଶିବମୋଗାରୁ ପୁଣେ ଆସିଥିଲେ, ତେଣୁ ତାଙ୍କୁ ଆଧାର କାର୍ଡରେ ଠିକଣା ବଦଳାଇବାର ଥିଲା। ସେ ସକାଳ ଆଠଟାରେ ଆଧାର କେନ୍ଦ୍ରରେ ପହଞ୍ଚିଲେ, କିନ୍ତୁ ଧାଡ଼ି ଆଗରୁ ଲମ୍ବା ହୋଇସାରିଥିଲା। ଜଣେ ଗାର୍ଡ ତାଙ୍କୁ ବୟାଳିଶ ନମ୍ବର ଟୋକେନ ଆଉ ପୂରଣ କରିବାକୁ ଏକ ଆବେଦନ ପତ୍ର ଦେଲେ। ତାଙ୍କ ପାଳି ଆସିବା ପରେ ଅଧିକାରୀ ତାଙ୍କ କାଗଜପତ୍ର ଯାଞ୍ଚ କଲେ ଏବଂ ଠିକଣା ପ୍ରମାଣ ଭାବେ ବିଜୁଳି ବିଲର ଫଟୋକପି ମାଗିଲେ। ଭାଗ୍ୟକୁ ଲକ୍ଷ୍ମୀ ଦୁଇଟି କପି ଆଣିଥିଲେ, ଆଉ ପ୍ରତି ପୃଷ୍ଠାରେ ଆଗରୁ ଦସ୍ତଖତ କରିସାରିଥିଲେ। ତା'ପରେ ଅଧିକାରୀ ଯାଞ୍ଚ ପାଇଁ ତାଙ୍କ ଆଙ୍ଗୁଠି ଛାପ ସ୍କାନ କଲେ ଏବଂ ଏକ ପ୍ରାପ୍ତି ରସିଦ ପ୍ରିଣ୍ଟ କଲେ। ସେ କହିଲେ ଦଶ ଦିନ ଭିତରେ ନୂଆ ଠିକଣା ଅପଡେଟ ହୋଇଯିବ, ଆଉ ଲକ୍ଷ୍ମୀ ଆଶ୍ୱସ୍ତ ହୋଇ ଦିନ ବାରଟା ଆଗରୁ ଅଫିସରୁ ବାହାରିଲେ।",
        "services|5:1|4|q0": "ଲକ୍ଷ୍ମୀ କାହିଁକି ଆଧାର କେନ୍ଦ୍ରକୁ ଗଲେ?",
