        "services|5:1|5|l2": "ଧନ୍ୟବାଦ। ମୋତେ ଆପଣଙ୍କ ଆଧାର କାର୍ଡ ଆଉ ଅନ୍ୟ ଗୋଟିଏ ଠିକଣା ପ୍ରମାଣ ଦରକାର। ଆପଣ କ'ଣ ଆଣିଛନ୍ତି?",
        "services|5:1|5|l3": "ମୋ ପାଖରେ ଆଧାର କାର୍ଡ, ଜନ୍ମ ତାରିଖ ପାଇଁ ଦଶମ ଶ୍ରେଣୀ ପ୍ରମାଣପତ୍ର, ଆଉ ନିକଟରେ ଆସିଥିବା ଗ୍ୟାସ ବିଲ ଅଛି।",
        "services|5:1|5|l4": "ଗ୍ୟାସ ବିଲଟି ଆପଣଙ୍କ ବାପାଙ୍କ ନାଁରେ ଅଛି। ଆପଣଙ୍କ ନିଜ ନାଁରେ କିଛି ଅଛି କି?",
        "services|5:1|5|l5": "ଦୁଃଖିତ, ନାହିଁ, କିନ୍ତୁ ମୁଁ ମୋ ଠିକଣା ଥିବା ବ୍ୟାଙ୍କ ପାସବୁକର ଫଟୋକପି ଆଣିଛି। ସେଥିରେ ଚଳିବ କି?",
        "services|5:1|5|l6": "ହଁ, ତାହା ଠିକ ଅଛି। ଦୟାକରି ଏଠି ଦସ୍ତଖତ କରନ୍ତୁ, ତା'ପରେ ଫଟୋ ଆଉ ଆଙ୍ଗୁଠି ଛାପ ପାଇଁ ବି କାଉଣ୍ଟରକୁ ଯାଆନ୍ତୁ।",
        "services|5:1|5|l7": "ନିଶ୍ଚୟ। ଏହା ପରେ ପୋଲିସ ଯାଞ୍ଚରେ କେତେ ସମୟ ଲାଗିବ?",
        "services|5:1|5|l8": "ସାଧାରଣତଃ ଦୁଇରୁ ତିନି ସପ୍ତାହ। ପୋଲିସ ଆପଣଙ୍କ ପାଖକୁ ଆସିବାକୁ ପ୍ରସ୍ତୁତ ହେଲେ ଆପଣ ଏସଏମଏସ ପାଇବେ।",
        "services|5:1|5|l9": "ଆପଣଙ୍କ ସାହାଯ୍ୟ ପାଇଁ ବହୁତ ଧନ୍ୟବାଦ, ମାଡାମ।",
        "services|5:1|5|q0": "ବିକ୍ରମ କାହିଁକି ଗ୍ୟାସ ବିଲ ବ୍ୟବହାର କରିପାରିଲେ ନାହିଁ?",
