        "services|6:1|1|p0": "ବେଙ୍ଗାଲୁରୁର ଘର ମାଲିକମାନେ ଅନେକ ସମୟରେ ଡିପୋଜିଟ ଭାବେ ଦଶ ମାସର ଭଡ଼ା ମାଗନ୍ତି।",
        "services|6:1|1|p1": "ଭଡ଼ା କିଛି କମ ହୋଇପାରିବ କି, ନା ଏହା ଶେଷ ଦର?",
        "services|6:1|1|p2": "ଦଲାଲ ତାଙ୍କ ଫି ଭାବେ ଗୋଟିଏ ମାସର ଭଡ଼ା ନିଅନ୍ତି।",
        "services|6:1|1|p3": "ଆମେ ମେଟ୍ରୋ ଷ୍ଟେସନ ପାଖରେ ପୁରା ଆସବାବପତ୍ର ଥିବା ଏକ ଫ୍ଲାଟ ଖୋଜୁଛୁ।",
        "services|6:1|1|p4": "ଭଡ଼ାଟିଆ ଭାବେ, ପ୍ରତ୍ୟେକ ପେମେଣ୍ଟର ରସିଦ ପାଇବା ଆପଣଙ୍କ ଅଧିକାର।",
        "services|6:1|2|w0": "ଭଡ଼ା ଚୁକ୍ତିପତ୍ର",
