        "services|6:1|2|w5": "ବିଜୁଳି ମିଟର",
        "services|6:1|3|p0": "ଦସ୍ତଖତ କରିବା ଆଗରୁ ଦୟାକରି ଭଡ଼ା ଚୁକ୍ତିପତ୍ର ଭଲ ଭାବେ ପଢ଼ନ୍ତୁ।",
        "services|6:1|3|p1": "ମାସିକ ରକ୍ଷଣାବେକ୍ଷଣ ଖର୍ଚ୍ଚ ଭଡ଼ାରେ ସାମିଲ ଅଛି, ନା ଅଲଗା?",
        "services|6:1|3|p2": "ଆମ ପଡ଼ୋଶୀମାନେ ମିଳାମିଶା, କିନ୍ତୁ ସେମାନେ ରାତି ଅଧରେ ଜୋରରେ ଗୀତ ବଜାନ୍ତି।",
        "services|6:1|3|p3": "ନୋଟିସ ଅବଧି ଦୁଇ ମାସ, ତେଣୁ ଜୁଲାଇ ସୁଦ୍ଧା ଆମକୁ ଘର ମାଲିକଙ୍କୁ ଜଣାଇବାକୁ ପଡ଼ିବ।",
        "services|6:1|3|p4": "ଫ୍ଲାଟ ଖାଲି କରିବା ବେଳେ ଆମେ ବିଜୁଳି ମିଟରର ରିଡିଂ ଲେଖି ରଖିବୁ।",
        "services|6:1|4|title": "ମହୀଶୂରରେ ନୂଆ ଫ୍ଲାଟ",
        "services|6:1|4|text": "ମହୀଶୂରରେ ଚାକିରି ପାଇବା ପରେ ଅନିତା କୁଭେମ୍ପୁନଗର ପାଖରେ ଏକ ଛୋଟ ଫ୍ଲାଟ ଖୋଜିବା ଆରମ୍ଭ କଲେ। ଜଣେ ଦଲାଲ ତାଙ୍କୁ ଚାରୋଟି ଜାଗା ଦେଖାଇଲେ, ଆଉ ତାଙ୍କୁ ଦ୍ୱିତୀୟ ମହଲାରେ ଆସବାବପତ୍ର ସହ ଏକ ୱାନ-ବେଡରୁମ ଫ୍ଲାଟ ପସନ୍ଦ ହେଲା। ଘର ମାଲିକ ଶ୍ରୀ ଗୌଡ଼ା ମାସକୁ ବାର ହଜାର ଟଙ୍କା ଭଡ଼ା ଆଉ ଷାଠିଏ ହଜାର ଟଙ୍କା ଡିପୋଜିଟ ମାଗିଲେ। ଅନିତା ଭଦ୍ର ଭାବେ ପଚାରିଲେ ଡିପୋଜିଟ ଟିକେ କମ ହୋଇପାରିବ କି, ଆଉ ଶେଷରେ ସେମାନେ ପଚାଶ ହଜାରରେ ରାଜି ହେଲେ। ଭଡ଼ା ଚୁକ୍ତିପତ୍ରରେ ଦସ୍ତଖତ କରିବା ଆଗରୁ ସେ ନୋଟିସ ଅବଧି ଦେଖିଲେ ଏବଂ ମାସିକ ରକ୍ଷଣାବେକ୍ଷଣ ଖର୍ଚ୍ଚ କିଏ ଦେବ ପଚାରିଲେ। ପରେ ବିଲ ନେଇ କୌଣସି ଦ୍ୱନ୍ଦ୍ୱ ନ ହେବା ପାଇଁ ସେ ବିଜୁଳି ମିଟରର ଗୋଟିଏ ଫଟୋ ମଧ୍ୟ ଉଠାଇଲେ। ପ୍ରଥମ ସନ୍ଧ୍ୟାରେ ଜଣେ ମିଳାମିଶା ପଡ଼ୋଶୀ ତାଙ୍କ ପାଇଁ ଏକ ପ୍ଲେଟ ଗରମ ବିସି ବେଲେ ବାଥ ଆଣିଲେ।",
        "services|6:1|4|q0": "ଶେଷରେ ଅନିତା କେତେ ଡିପୋଜିଟ ଦେବାକୁ ରାଜି ହେଲେ?",
