        "services|6:1|4|q1": "ସେ ବିଜୁଳି ମିଟରର ଫଟୋ କାହିଁକି ଉଠାଇଲେ?",
        "services|6:1|4|q1o0": "ପରେ ବିଲ ନେଇ ଦ୍ୱନ୍ଦ୍ୱ ଏଡ଼ାଇବା ପାଇଁ",
