        "services|6:1|5|title": "ଘର ମାଲିକାଣୀଙ୍କୁ ଫୋନ",
        "services|6:1|5|scenario": "ପୁଣେର ଜଣେ ଭଡ଼ାଟିଆ ରାହୁଲ, ଫ୍ଲାଟର ଏକ ସମସ୍ୟା ଆଉ ଘର ଛାଡ଼ିବା ବିଷୟରେ ତାଙ୍କ ଘର ମାଲିକାଣୀ ଶ୍ରୀମତୀ ଯୋଶୀଙ୍କୁ ଫୋନ କରନ୍ତି।",
        "services|6:1|5|l0": "ଶୁଭ ସନ୍ଧ୍ୟା, ଶ୍ରୀମତୀ ଯୋଶୀ। ମୁଁ ଫ୍ଲାଟ 3ବିରୁ ରାହୁଲ କହୁଛି। ଆପଣଙ୍କ ପାଖରେ ଟିକେ ସମୟ ଅଛି କି?",
        "services|6:1|5|l1": "ହଁ, ରାହୁଲ, କୁହ। ସବୁ ଠିକ ଅଛି ତ?",
        "services|6:1|5|l2": "ପୁରା ନୁହେଁ। ସୋମବାରଠାରୁ ବାଥରୁମ ଛାତରୁ ପାଣି ଚୁଉଛି, ଆଉ କାନ୍ଥ ଓଦା ହୋଇଯାଉଛି।",
        "services|6:1|5|l3": "ହାୟ ହାୟ। ନିଶ୍ଚୟ ଛାତ ଉପରର ଟାଙ୍କିରୁ ହେଉଥିବ। ମୁଁ କାଲି ସକାଳେ ଆମ ପ୍ଲମ୍ବର ସୁନୀଲଙ୍କୁ ପଠାଇବି।",
        "services|6:1|5|l4": "ଧନ୍ୟବାଦ। ମରାମତି ଖର୍ଚ୍ଚ ରକ୍ଷଣାବେକ୍ଷଣରୁ ଯିବ, ନା ମୋତେ ଦେବାକୁ ପଡ଼ିବ?",
        "services|6:1|5|l5": "ଚିନ୍ତା କର ନାହିଁ, ଘର ମାଲିକାଣୀ ଭାବେ ଏହା ମୋ ଦାୟିତ୍ୱ। ତୁମେ କେବଳ ବଲ୍ବ ଭଳି ଛୋଟ ଜିନିଷ ପାଇଁ ଦିଅ।",
        "services|6:1|5|l6": "ଆପଣଙ୍କ ବଡ଼ପଣ। ଆଉ ଗୋଟିଏ କଥା: ମୋ କମ୍ପାନୀ ମୋତେ ମାର୍ଚ୍ଚରେ ନାସିକ ବଦଳି କରୁଛି।",
        "services|6:1|5|l7": "ଆଚ୍ଛା। ଚୁକ୍ତି ଅନୁସାରେ ନୋଟିସ ଅବଧି ଦୁଇ ମାସ, ତେଣୁ ଜାନୁଆରୀ ସୁଦ୍ଧା ମୋତେ ଲିଖିତ ନୋଟିସ ଦିଅ।",
        "services|6:1|5|l8": "ମୁଁ ଏହି ସପ୍ତାହରେ ଆପଣଙ୍କୁ ନୋଟିସ ଇମେଲ କରିଦେବି। ଆଉ ଖାଲି କରିବା ବେଳେ ଡିପୋଜିଟ ଫେରସ୍ତ ମିଳିବ, ନୁହେଁ କି?",
        "services|6:1|5|l9": "ହଁ। ଫ୍ଲାଟ ଆଉ ଶେଷ ବିଜୁଳି ବିଲ ଦେଖିସାରିବା ପରେ, ମୁଁ ଏକ ସପ୍ତାହ ଭିତରେ ଟ୍ରାନ୍ସଫର କରିଦେବି।",
