        "society|1:1|1|p1": "ସାମ୍ବାଦିକ ଜଣକ ନିଜେ ଚାଷୀଙ୍କ ସହ କଥା ହେବାକୁ କଲବୁର୍ଗି ଗଲେ।",
        "society|1:1|1|p2": "ସମ୍ବାଦ ପାଠକ କହିଲେ ଯେ ଆଜି ରାତିରେ ମ୍ୟାଚଟି ସିଧା ପ୍ରସାରଣ ହେବ।",
