        "society|1:1|2|w2": "ବିବାଦ",
        "society|1:1|2|w3": "ପ୍ରତ୍ୟକ୍ଷଦର୍ଶୀ",
        "society|1:1|2|w4": "ସଦ୍ୟତମ ଖବର",
        "society|1:1|2|w5": "ପ୍ରତିକ୍ରିୟା",
        "society|1:1|3|p0": "ଜଣେ ପ୍ରତ୍ୟକ୍ଷଦର୍ଶୀଙ୍କ କହିବା ଅନୁସାରେ, ବସଟି ହଠାତ ବ୍ରେକ ମାରି ଡିଭାଇଡରରେ ଧକ୍କା ଦେଲା।",
        "society|1:1|3|p1": "ରେଳ ଷ୍ଟେସନ ପାଖରେ ଘଟିଥିବା ଘଟଣାର ପୋଲିସ ଏବେ ବି ତଦନ୍ତ କରୁଛି।",
        "society|1:1|3|p2": "ସାମ୍ବାଦିକ ସମ୍ମିଳନୀରେ ମନ୍ତ୍ରୀ ଯାହା କହିଲେ, ସେଥିରୁ ଏକ ବଡ଼ ବିବାଦ ଆରମ୍ଭ ହେଲା।",
        "society|1:1|3|p3": "ପେଜଟି ବାରମ୍ବାର ରିଫ୍ରେସ କରୁଥାଅ; ସେମାନେ ପ୍ରତି ଦଶ ମିନିଟରେ ସଦ୍ୟତମ ଖବର ଦିଅନ୍ତି।",
        "society|1:1|3|p4": "ଖବରଟି ଶୁଣିବା ପରେ ତୁମର ପ୍ରଥମ ପ୍ରତିକ୍ରିୟା କ'ଣ ଥିଲା?",
        "society|1:1|4|title": "ଯେଉଁ ପୋଲ ଭାଙ୍ଗି ନ ଥିଲା",
        "society|1:1|4|text": "ଦିନେ ସନ୍ଧ୍ୟାରେ ମହୀଶୂରରେ ଏକ ମେସେଜ ବ୍ୟାପିଗଲା ଯେ ଶ୍ରୀରଙ୍ଗପଟ୍ଟଣା ପାଖରେ ପୁରୁଣା ପୋଲଟି ଭାଙ୍ଗିପଡ଼ିଛି। କଲେଜ ଛାତ୍ର ରାହୁଲ ତାହା ପ୍ରାୟ ତାଙ୍କ ପରିବାର ଗ୍ରୁପକୁ ଫରୱାର୍ଡ କରିଦେଉଥିଲେ, କିନ୍ତୁ ତା'ପରେ ଅଟକିଗଲେ। ସେ ଏକ ବିଶ୍ୱସନୀୟ ଖବର ୱେବସାଇଟ ଖୋଲିଲେ ଏବଂ ଏମିତି କୌଣସି ଶିରୋନାମା ପାଇଲେ ନାହିଁ। ତା' ବଦଳରେ ସେ ପୋଲ ପାଖରେ ଠିଆ ହୋଇଥିବା ଜଣେ ସ୍ଥାନୀୟ ସାମ୍ବାଦିକଙ୍କ ଏକ ଛୋଟ ସଦ୍ୟତମ ଖବର ଦେଖିଲେ। ସେ ଜଣେ ପ୍ରତ୍ୟକ୍ଷଦର୍ଶୀଙ୍କ ସହ କଥା ହୋଇଥିଲେ, ଯିଏ କହିଲେ ଯେ କେବଳ ରେଲିଂର ଏକ ଛୋଟ ଅଂଶ ନଦୀରେ ଖସିପଡ଼ିଥିଲା। କେହି ଆହତ ହୋଇ ନ ଥିଲେ, ଆଉ ପୋଲଟି ଏବେ ବି ଖୋଲା ଥିଲା। ରାହୁଲ ବୁଝିଲେ ଯେ ମେସେଜଟି ଏକ ଛୋଟ ଘଟଣାରୁ ତିଆରି ହୋଇଥିବା ଗୁଜବ ମାତ୍ର। ସେ ଗ୍ରୁପରେ ପ୍ରକୃତ ଖବର ପୋଷ୍ଟ କଲେ ଏବଂ ସେୟାର କରିବା ଆଗରୁ ଯାଞ୍ଚ କରିବାକୁ ସମସ୍ତଙ୍କୁ କହିଲେ।",
        "society|1:1|4|q0": "ମେସେଜରେ କ'ଣ କୁହାଯାଇଥିଲା?",
        "society|1:1|4|q0o0": "ପୁରୁଣା ପୋଲଟି ଭାଙ୍ଗିପଡ଼ିଛି",
        "society|1:1|4|q0o1": "ନଦୀ ବନ୍ୟାରେ ସହର ବୁଡ଼ିଯାଇଛି",
        "society|1:1|4|q0o2": "କଲେଜ ବନ୍ଦ ହୋଇଛି",
        "society|1:1|4|q0o3": "ଏକ ବସ ନଦୀରେ ପଡ଼ିଯାଇଛି",
