        "society|1:1|4|q1o2": "ରାହୁଲଙ୍କ ପରିବାର",
        "society|1:1|4|q1o3": "ଜଣେ ସମ୍ବାଦ ପାଠକ",
        "society|1:1|4|q2": "ଶେଷରେ ରାହୁଲ କ'ଣ କଲେ?",
        "society|1:1|4|q2o0": "ସେ ପ୍ରକୃତ ଖବର ସେୟାର କଲେ ଏବଂ ସମସ୍ତଙ୍କୁ ଆଗରୁ ଯାଞ୍ଚ କରିବାକୁ କହିଲେ",
        "society|1:1|4|q2o1": "ସେ ମେସେଜଟି ପରିବାରକୁ ଫରୱାର୍ଡ କଲେ",
        "society|1:1|4|q2o2": "ସେ ନିଜେ ପୋଲ ଦେଖିବାକୁ ଗଲେ",
        "society|1:1|4|q2o3": "ସେ ଖବରକାଗଜ ଅଫିସକୁ ଫୋନ କଲେ",
        "society|1:1|5|title": "କାଲି ରାତିର ଝଡ଼",
        "society|1:1|5|scenario": "ବେଙ୍ଗାଲୁରୁ ଅଫିସରେ କଫି ପିଇ ପିଇ ଦୁଇ ସହକର୍ମୀ ଦିବ୍ୟା ଓ ଇମରାନ ସକାଳର ଖବର ବିଷୟରେ କଥା ହୁଅନ୍ତି।",
        "society|1:1|5|l0": "ଇମରାନ, ଆଜି ସକାଳର ଖବର ଦେଖିଲ କି? କାଲି ରାତିରେ ବେଙ୍ଗାଲୁରୁରେ ବହୁତ ବଡ଼ ଝଡ଼ ହୋଇଥିଲା।",
        "society|1:1|5|l1": "ମୁଁ ଶିରୋନାମା ଦେଖିଲି, କିନ୍ତୁ ପୁରା ଖବର ପଢ଼ିଲି ନାହିଁ। କ'ଣ ହେଲା?",
        "society|1:1|5|l2": "ଶୁଣିଲି ଜୟନଗରରେ ଠିଆ ହୋଇଥିବା ଏକ ବସ ଉପରେ ଗୋଟିଏ ବଡ଼ ଗଛ ପଡ଼ିଲା। ଭାଗ୍ୟକୁ ବସଟି ଖାଲି ଥିଲା।",
        "society|1:1|5|l3": "ଭଗବାନଙ୍କୁ ଧନ୍ୟବାଦ। କେହି ଆହତ ହୋଇଥିଲେ କି?",
        "society|1:1|5|l4": "ନା। ଜଣେ ପ୍ରତ୍ୟକ୍ଷଦର୍ଶୀ ସାମ୍ବାଦିକଙ୍କୁ କହିଲେ ଯେ ଡ୍ରାଇଭର ମାତ୍ର ଏକ ମିନିଟ ଆଗରୁ ଚା' ପିଇବାକୁ ଓହ୍ଲାଇଥିଲେ।",
        "society|1:1|5|l5": "ଏହା ତ ଅବିଶ୍ୱସନୀୟ ଭାଗ୍ୟ। ମୁଁ ଏକ ଗୁଜବ ବି ଶୁଣିଲି ଯେ ମେଟ୍ରୋ ବନ୍ଦ ହୋଇଯାଇଥିଲା। ଏହା ସତ କି?",
        "society|1:1|5|l6": "କେବଳ ଘଣ୍ଟାଏ ପାଇଁ। ସଦ୍ୟତମ ଖବର କହୁଛି ସବୁ ଲାଇନ ପୁଣି ସାଧାରଣ ଭାବେ ଚାଲୁଛି।",
        "society|1:1|5|l7": "ସତ କହିଲେ, ମୋର ପ୍ରଥମ ପ୍ରତିକ୍ରିୟା ହେଉଛି ଖରାପ ଯୋଜନାକୁ ଦୋଷ ଦେବା। ବର୍ଷା ଋତୁ ଆଗରୁ ପୁରୁଣା ଗଛଗୁଡ଼ିକ କାହିଁକି ଯାଞ୍ଚ ହୁଏ ନାହିଁ?",
        "society|1:1|5|l8": "ଆଜିର ସମ୍ପାଦକୀୟ ଠିକ ଏହା ହିଁ କହୁଛି। ସିଟି କର୍ପୋରେସନ ପ୍ରତ୍ୟେକ ପୁରୁଣା ଗଛର ସର୍ଭେ କରିବାକୁ ପ୍ରତିଶ୍ରୁତି ଦେଇଛି।",
        "society|1:1|5|l9": "ହଉ, ଆଶା କରୁଛି ଏଥର ସେମାନେ ସେହି ପ୍ରତିଶ୍ରୁତି ରଖିବେ।",
        "society|1:1|5|q0": "ଗଛଟି କେଉଁଠି ପଡ଼ିଲା?",
