        "society|6:1|5|q1": "ଲୋକେ ନଗଦ ଦାନ କିପରି ଦେବା ଉଚିତ?",
        "society|6:1|5|q1o0": "କେବଳ ଅଫିସିଆଲ ୟୁପିଆଇ ଆଇଡି ମାଧ୍ୟମରେ, ରସିଦ ସହ",
        "society|6:1|5|q1o1": "ଯେକୌଣସି ସ୍ୱେଚ୍ଛାସେବୀଙ୍କୁ ନଗଦରେ",
        "society|6:1|5|q1o2": "ସମୀରଙ୍କ ନିଜ ଖାତାରେ",
        "society|6:1|5|q1o3": "ନଗଦ ଆଦୌ ନିଆଯିବ ନାହିଁ",
        "society|6:1|5|q2": "କାଲି ସକାଳୁ ସକାଳୁ ସମୀର କ'ଣ କରିବେ?",
        "society|6:1|5|q2o0": "ତିରପାଲ ନେଇ ବୁଢ଼ା ଦମ୍ପତିଙ୍କ ପାଖକୁ ଯିବେ",
        "society|6:1|5|q2o1": "ପୁରୁଣା ଲୁଗା ସଂଗ୍ରହ କରିବେ",
        "society|6:1|5|q2o2": "ବ୍ୟାଙ୍କକୁ ଯିବେ",
        "society|6:1|5|q2o3": "ସରକାରୀ ସ୍କୁଲରେ ପଢ଼ାଇବେ",
        "workplace|1:1|0|w0": "ଭୂମିକା",
        "workplace|1:1|0|w1": "ବିଭାଗ",
        "workplace|1:1|0|w2": "ପଦବୀ",
        "workplace|1:1|0|w3": "କାର୍ଯ୍ୟ",
        "workplace|1:1|0|w4": "ତଦାରଖ କରିବା",
        "workplace|1:1|0|w5": "ସମ୍ଭାଳିବା",
        "workplace|1:1|1|p0": "ମୋ ବର୍ତ୍ତମାନର ଭୂମିକାରେ, ମୁଁ ପୁରା କମ୍ପାନୀର ଦରମା ହିସାବ ଦେଖେ।",
        "workplace|1:1|1|p1": "ଆପଣ କେଉଁ ବିଭାଗରେ କାମ କରନ୍ତି, ଆଉ କାହାକୁ ରିପୋର୍ଟ କରନ୍ତି?",
        "workplace|1:1|1|p2": "କାଗଜରେ ମୋ ପଦବୀ ସିନିୟର ଆନାଲିଷ୍ଟ, କିନ୍ତୁ ମୋ କାର୍ଯ୍ୟ ପ୍ରତି ସପ୍ତାହରେ ବଦଳେ।",
        "workplace|1:1|1|p3": "ମୁଁ ଛଅ ଜଣିଆ ଟିମର ତଦାରଖ କରେ ଏବଂ କ୍ଲାଏଣ୍ଟଙ୍କ ଅଧିକାଂଶ କଲ ସମ୍ଭାଳେ।",
        "workplace|1:1|1|p4": "ସାଧାରଣ ଦିନରେ, ମୁଁ ଲଞ୍ଚ ଆଗରୁ ଜରୁରୀ କାମ ସାରିଦିଏ ଏବଂ ବାକି କାମର ଯୋଜନା କରେ।",
        "workplace|1:1|2|w0": "ମୁଖ୍ୟାଳୟ",
        "workplace|1:1|2|w1": "ଷ୍ଟାର୍ଟଅପ",
        "workplace|1:1|2|w2": "ଉତ୍ପାଦନ କରିବା",
        "workplace|1:1|2|w3": "କର୍ମୀବଳ",
        "workplace|1:1|2|w4": "ଦକ୍ଷତା",
        "workplace|1:1|2|w5": "ବିଶେଷଜ୍ଞ ହେବା",
        "workplace|1:1|3|p0": "ଆମ ମୁଖ୍ୟାଳୟ ବେଙ୍ଗାଲୁରୁରେ, କିନ୍ତୁ ଆମ ଅଧିକାଂଶ କର୍ମୀବଳ ହୁବ୍ବଳିରେ ଅଛନ୍ତି।",
        "workplace|1:1|3|p1": "ଆମେ ଏକ ଛୋଟ ଷ୍ଟାର୍ଟଅପ, ଯାହା କ୍ଲିନିକ ପାଇଁ ବିଲିଂ ସଫ୍ଟୱେର ତିଆରି କରେ।",
        "workplace|1:1|3|p2": "ମହୀଶୂର ପାଖରେ ଥିବା ଆମ କାରଖାନା ଭାରତର ଅଧିକାଂଶ ଟୁ-ହୁଇଲର ବ୍ରାଣ୍ଡ ପାଇଁ ବ୍ରେକ ପାର୍ଟ ଉତ୍ପାଦନ କରେ।",
        "workplace|1:1|3|p3": "ଗ୍ରାମୀଣ ସ୍ୱାସ୍ଥ୍ୟସେବାରେ ଆମର ଦକ୍ଷତା ହିଁ ଆମକୁ ଅଲଗା କରେ।",
        "workplace|1:1|3|p4": "ଛୋଟ ସହରର ଦୋକାନଗୁଡ଼ିକୁ ଅନଲାଇନରେ ବିକ୍ରି ଆରମ୍ଭ କରିବାରେ ସାହାଯ୍ୟ କରିବା ଆମର ବିଶେଷତ୍ୱ।",
        "workplace|1:1|4|title": "ଆପଣ ପ୍ରକୃତରେ କ'ଣ କରନ୍ତି?",
        "workplace|1:1|4|text": "ଧାରୱାଡ଼ରେ ଏକ ପାରିବାରିକ ବାହାଘରରେ ନିଖିଲଙ୍କ ମାମୁଁ ତାଙ୍କୁ ପଚାରିଲେ ସେ କାମରେ ପ୍ରକୃତରେ କ'ଣ କରନ୍ତି। ନିଖିଲ ବୁଝାଇଲେ ଯେ ସେ ଏକ ଷ୍ଟାର୍ଟଅପରେ କାମ କରନ୍ତି, ଯାହା ଚାଷୀଙ୍କ ପାଇଁ ମାଟି ସେନ୍ସର ତିଆରି କରେ। କମ୍ପାନୀର ମୁଖ୍ୟାଳୟ ବେଙ୍ଗାଲୁରୁରେ, କିନ୍ତୁ ସେନ୍ସରଗୁଡ଼ିକ ହୁବ୍ବଳି ପାଖରେ ଏକ ଛୋଟ କାରଖାନାରେ ଉତ୍ପାଦନ ହୁଏ। ତାଙ୍କ ପଦବୀ ପ୍ରଡକ୍ଟ ଇଞ୍ଜିନିୟର, ଆଉ ସେ ଟେଷ୍ଟିଂ ବିଭାଗରେ ଅଛନ୍ତି। ତାଙ୍କ ମୁଖ୍ୟ କାର୍ଯ୍ୟ ହେଉଛି ପ୍ରତ୍ୟେକ ନୂଆ ସେନ୍ସର ଚାଷୀଙ୍କ ପାଖକୁ ଯିବା ଆଗରୁ ଯାଞ୍ଚ କରିବା। ସେ ଦୁଇଜଣ ଜୁନିୟର ଇଞ୍ଜିନିୟରଙ୍କ ତଦାରଖ ମଧ୍ୟ କରନ୍ତି ଏବଂ କାରଖାନା ଟିମର ପ୍ରଶ୍ନ ସମ୍ଭାଳନ୍ତି। ମାମୁଁ ହସି କହିଲେ ନିଶ୍ଚୟ କମ୍ପାନୀର ବହୁତ ବଡ଼ କର୍ମୀବଳ ଥିବ। ନିଖିଲ ହସି କହିଲେ ମାତ୍ର ଚାଳିଶ ଜଣ ଲୋକ ଅଛନ୍ତି, କିନ୍ତୁ ପ୍ରତ୍ୟେକଙ୍କର ପ୍ରକୃତ ଦକ୍ଷତା ଅଛି।",
        "workplace|1:1|4|q0": "ନିଖିଲଙ୍କ କମ୍ପାନୀ କ'ଣ ତିଆରି କରେ?",
        "workplace|1:1|4|q0o0": "ଚାଷୀଙ୍କ ପାଇଁ ମାଟି ସେନ୍ସର",
        "workplace|1:1|4|q0o1": "ସ୍କୁଟର ପାଇଁ ବ୍ରେକ ପାର୍ଟ",
        "workplace|1:1|4|q0o2": "କ୍ଲିନିକ ପାଇଁ ବିଲିଂ ସଫ୍ଟୱେର",
        "workplace|1:1|4|q0o3": "ବାହାଘର କାର୍ଡ",
        "workplace|1:1|4|q1": "ସେନ୍ସରଗୁଡ଼ିକ କେଉଁଠି ଉତ୍ପାଦନ ହୁଏ?",
        "workplace|1:1|4|q1o0": "ହୁବ୍ବଳି ପାଖରେ",
