        "workplace|1:1|5|title": "ତେବେ, ଆପଣ କ'ଣ କରନ୍ତି?",
        "workplace|1:1|5|scenario": "ବେଙ୍ଗାଲୁରୁର ଏକ ବ୍ୟବସାୟିକ କାର୍ଯ୍ୟକ୍ରମରେ ଅନନ୍ୟା ଓ ଫରହାନ ପ୍ରଥମ ଥର ଭେଟନ୍ତି ଏବଂ ନିଜ ନିଜ ଚାକିରି ବିଷୟରେ କଥା ହୁଅନ୍ତି।",
        "workplace|1:1|5|l0": "ନମସ୍କାର, ମୁଁ ସହ୍ୟାଦ୍ରି ଲଜିଷ୍ଟିକ୍ସରୁ ଫରହାନ। ଆପଣ ଏହି କାର୍ଯ୍ୟକ୍ରମକୁ କେମିତି ଆସିଲେ?",
        "workplace|1:1|5|l1": "ଆପଣଙ୍କୁ ଭେଟି ଖୁସି ଲାଗିଲା। ମୁଁ ଅନନ୍ୟା। ମୁଁ ଏକ ଫିନଟେକ ଷ୍ଟାର୍ଟଅପରେ କଷ୍ଟମର ସପୋର୍ଟ ଟିମର ମୁଖ୍ୟ।",
        "workplace|1:1|5|l2": "ବଢ଼ିଆ। ଆପଣଙ୍କ କମ୍ପାନୀ ଠିକ କ'ଣ କରେ?",
        "workplace|1:1|5|l3": "ଆମେ ଏକ ଆପ ତିଆରି କରିଛୁ, ଯାହା ଛୋଟ ଦୋକାନୀଙ୍କୁ ହିସାବ ରଖିବାରେ ଏବଂ ଡିଜିଟାଲ ପେମେଣ୍ଟ ନେବାରେ ସାହାଯ୍ୟ କରେ।",
        "workplace|1:1|5|l4": "ଆଉ ଆପଣଙ୍କ ସାଧାରଣ ଦିନଟି କେମିତି କଟେ?",
        "workplace|1:1|5|l5": "ମୁଁ ଟିମ ସହ ଏକ ଛୋଟ କଲରେ ଆରମ୍ଭ କରେ, ତା'ପରେ କଠିନ ଅଭିଯୋଗଗୁଡ଼ିକ ନିଜେ ସମ୍ଭାଳେ।",
        "workplace|1:1|5|l6": "ବହୁତ ଚାପର କାମ ଲାଗୁଛି। ଆପଣଙ୍କ ଟିମ କେତେ ବଡ଼?",
        "workplace|1:1|5|l7": "ଦୁଇ ସିଫ୍ଟରେ ବାର ଜଣ। ଆଉ ଆପଣ? ଆପଣଙ୍କ ଭୂମିକା କ'ଣ?",
        "workplace|1:1|5|l8": "ମୁଁ ଜଣେ ରୁଟ ପ୍ଲାନର। ମୋଟାମୋଟି, ଆମ ଟ୍ରକଗୁଡ଼ିକ ସବୁଠୁ ଶୀଘ୍ର ଆଉ ଶସ୍ତା ରାସ୍ତାରେ ଯାଆନ୍ତୁ, ସେଥିପ୍ରତି ମୁଁ ଧ୍ୟାନ ଦିଏ।",
        "workplace|1:1|5|l9": "ତାହେଲେ ଆପଣଙ୍କ ଯୋଗୁଁ ମୋ ପାର୍ସଲ ଠିକ ସମୟରେ ପହଞ୍ଚେ! ଯୋଗାଯୋଗରେ ରହିବା।",
        "workplace|1:1|5|q0": "ଅନନ୍ୟାଙ୍କ କମ୍ପାନୀ କ'ଣ ତିଆରି କରିଛି?",
