        "workplace|2:1|0|w5": "ଅଂଶଗ୍ରହଣକାରୀ",
        "workplace|2:1|1|p0": "ଯିଏ କଥା କହୁନାହାନ୍ତି, ଦୟାକରି ସମସ୍ତେ ନିଜକୁ ମ୍ୟୁଟ କରିବେ କି?",
        "workplace|2:1|1|p1": "ମୁଁ ଏଇନେ ଟିମ ଚାଟରେ ମିଟିଂ ଲିଙ୍କ ପଠାଇଦେଲି।",
        "workplace|2:1|1|p2": "ରବି, ତୁମ ୱେବକ୍ୟାମ ବନ୍ଦ ଅଛି; ଗୋଟିଏ ମିନିଟ ପାଇଁ ଅନ କରିପାରିବ କି?",
        "workplace|2:1|1|p3": "କେବଳ ହୋଷ୍ଟ ହିଁ ୱେଟିଂ ରୁମରୁ ଅଂଶଗ୍ରହଣକାରୀଙ୍କୁ ଭିତରକୁ ଆଣିପାରିବେ।",
        "workplace|2:1|1|p4": "ଦୟାକରି ହେଡସେଟ ପିନ୍ଧ, ଯାହାଫଳରେ ତୁମ ପଛର ଟ୍ରାଫିକ ଶବ୍ଦ ଆମକୁ ଶୁଭିବ ନାହିଁ।",
        "workplace|2:1|2|w0": "ଅସ୍ଥିର",
        "workplace|2:1|2|w1": "ଡେରି",
        "workplace|2:1|2|w2": "ଅଟକିଯିବା",
        "workplace|2:1|2|w3": "ପ୍ରତିଧ୍ୱନି",
        "workplace|2:1|2|w4": "ରେକର୍ଡିଂ",
        "workplace|2:1|2|w5": "ଫଲୋ-ଅପ",
        "workplace|2:1|3|p0": "ଦୁଃଖିତ, ମୋ ସଂଯୋଗ ଅସ୍ଥିର ଅଛି; ମୁଁ ମୋ ଭିଡିଓ ବନ୍ଦ କରିଦେଉଛି।",
        "workplace|2:1|3|p1": "କିଛି ସେକେଣ୍ଡର ଡେରି ହେଉଛି, ତେଣୁ ଚାଲ ଏକାବେଳେ କଥା ନ କହିବା।",
        "workplace|2:1|3|p2": "ତୁମ ସ୍କ୍ରିନ ଅଟକିଯାଇଛି; ପୁଣି ସେୟାର କରିପାରିବ କି?",
        "workplace|2:1|3|p3": "ମୋତେ ପ୍ରତିଧ୍ୱନି ଶୁଭୁଛି; କାହାର ଲ୍ୟାପଟପ ସ୍ପିକର ତାଙ୍କ ମାଇକ୍ର ବହୁତ ପାଖରେ ଅଛି।",
        "workplace|2:1|3|p4": "ଆଜି ସନ୍ଧ୍ୟା ସୁଦ୍ଧା ମୁଁ ରେକର୍ଡିଂ ଆଉ ଏକ ଛୋଟ ଫଲୋ-ଅପ ଇମେଲ ପଠାଇଦେବି।",
        "workplace|2:1|4|title": "ବାରମ୍ବାର ଅଟକୁଥିବା କଲ",
        "workplace|2:1|4|text": "ପ୍ରତି ସୋମବାର ଦୀପା ମହୀଶୂରର ତାଙ୍କ ଟିମ ଆଉ ପୁଣେର ସେଲ୍ସ ଟିମ ମଧ୍ୟରେ ଏକ ଭିଡିଓ କଲ ହୋଷ୍ଟ କରନ୍ତି। ଗତ ସପ୍ତାହରେ କଲଟି ଖରାପ ଭାବେ ଆରମ୍ଭ ହେଲା। ବାର ଜଣ ଅଂଶଗ୍ରହଣକାରୀ ଯୋଗ ଦେଲେ, କିନ୍ତୁ ସେମାନଙ୍କ ମଧ୍ୟରୁ ତିନିଜଣ ଲିଙ୍କ ଖୋଲିପାରିଲେ ନାହିଁ। ତା'ପରେ ଜୋର ପ୍ରତିଧ୍ୱନି ହେଲା, କାରଣ ସୁରେଶ ଏକାସାଙ୍ଗରେ ଲ୍ୟାପଟପ ଆଉ ଫୋନ ଦୁହିଁରୁ ଯୋଗ ଦେଇଥିଲେ। ଦୀପା ତାଙ୍କ ସ୍କ୍ରିନ ସେୟାର କରିବା ଆରମ୍ଭ କରନ୍ତେ ତାହା ଅଟକିଗଲା, ଆଉ ତାଙ୍କ ସ୍ୱର ବହୁତ ଡେରିରେ ପୁଣେ ପହଞ୍ଚିଲା। ସେ ଶାନ୍ତ ଭାବେ ସମସ୍ତଙ୍କୁ ମ୍ୟୁଟ କରିବାକୁ, ୱେବକ୍ୟାମ ବନ୍ଦ କରିବାକୁ ଏବଂ ହେଡସେଟ ବ୍ୟବହାର କରିବାକୁ କହିଲେ। ସଂଯୋଗ ଭଲ ହେଲା, ଆଉ ମିଟିଂ ମାତ୍ର ଦଶ ମିନିଟ ଡେରିରେ ଶେଷ ହେଲା। ସେଦିନ ସନ୍ଧ୍ୟାରେ ଦୀପା ରେକର୍ଡିଂ ଆଉ ପ୍ରତ୍ୟେକ ନିଷ୍ପତ୍ତି ଓ ସମୟସୀମା ଥିବା ଏକ ସ୍ପଷ୍ଟ ଫଲୋ-ଅପ ଇମେଲ ପଠାଇଲେ।",
        "workplace|2:1|4|q0": "ଜୋର ପ୍ରତିଧ୍ୱନି କାହିଁକି ହେଲା?",
