        "workplace|2:1|5|scenario": "କାର୍ତ୍ତିକ ହୁବ୍ବଳିରେ ତାଙ୍କ ଘରୁ ଏକ ଅନଲାଇନ ପ୍ରୋଜେକ୍ଟ ମିଟିଂରେ ଯୋଗ ଦିଅନ୍ତି। ହୋଷ୍ଟ ମୀରା ତାଙ୍କ ଶବ୍ଦ ଆଉ ସ୍କ୍ରିନରେ ସାହାଯ୍ୟ କରନ୍ତି।",
