        "workplace|2:1|5|l1": "ଦୁଃଖିତ। ଏବେ ମୋ କଥା ଶୁଭୁଛି କି?",
        "workplace|2:1|5|l2": "ହଁ, ବହୁତ ସ୍ପଷ୍ଟ। ତୁମ ସ୍କ୍ରିନ ସେୟାର କରି ଟେଷ୍ଟ ଫଳାଫଳ ଆମକୁ ବୁଝାଇପାରିବ କି?",
