        "workplace|2:1|5|l5": "ମୋ ସଂଯୋଗ ବାରମ୍ବାର କଟିଯାଉଛି। ମୁଁ ଭିଡିଓ ବନ୍ଦ କରି ପୁଣି ଚେଷ୍ଟା କରୁଛି।",
        "workplace|2:1|5|l6": "ଏବେ ବହୁତ ଭଲ, ଚାଲୁଛି। ଆଗକୁ କୁହ।",
        "workplace|2:1|5|l7": "ଧନ୍ୟବାଦ। ଯେମିତି ଦେଖୁଛନ୍ତି, ଏହି ସପ୍ତାହର ନବେ ପ୍ରତିଶତ ଟେଷ୍ଟ ପାସ ହୋଇଛି।",
        "workplace|2:1|5|l8": "ବହୁତ ଭଲ କାମ। ମୁଁ ଏହା ରେକର୍ଡ କରୁଛି, ଯାହାଫଳରେ ପୁଣେ ଟିମ ପରେ ଦେଖିପାରିବେ।",
