        "workplace|3:1|1|p0": "ଆଜି ଆମେ କ'ଣ ସବୁ ଆଲୋଚନା କରିବା, ତା'ର ଏକ ସଂକ୍ଷିପ୍ତ ବିବରଣୀରୁ ଆରମ୍ଭ କରୁଛି।",
        "workplace|3:1|1|p1": "ଏହି ସ୍ଲାଇଡରେ ଯେମିତି ଦେଖୁଛନ୍ତି, ମାର୍ଚ୍ଚ ପରେ ବିକ୍ରି ଦୁଇଗୁଣ ହୋଇଗଲା।",
