        "workplace|3:1|2|w5": "ସାରାଂଶ କହିବା",
        "workplace|3:1|3|p0": "କେହି ପ୍ରୋଜେକ୍ଟରଟି ଦେଖିବେ କି? ସ୍ଲାଇଡଗୁଡ଼ିକ ବହୁତ ଅନ୍ଧାର ଦେଖାଯାଉଛି।",
        "workplace|3:1|3|p1": "ମୁଁ ପୁରା ଭାଷଣଟି ଦୁଇଥର ଅଭ୍ୟାସ କରିଛି, ତେଣୁ କେତେ ସମୟ ଲାଗେ ମୁଁ ଠିକ ଜାଣେ।",
        "workplace|3:1|3|p2": "ସବୁ ସଂଖ୍ୟା ଥିବା ଏକ ହ୍ୟାଣ୍ଡଆଉଟ ଅଛି, ତେଣୁ ଆପଣଙ୍କୁ ନୋଟ ନେବା ଦରକାର ନାହିଁ।",
