        "workplace|3:1|3|p4": "ଶେଷରେ, ମୁଁ ଏକ ମିନିଟରେ ତିନୋଟି ମୁଖ୍ୟ କଥାର ସାରାଂଶ କହୁଛି।",
        "workplace|3:1|4|title": "ରେଖାଙ୍କ ବଡ଼ ଦିନ",
        "workplace|3:1|4|text": "ହୁବ୍ବଳିର ଜଣେ ମାର୍କେଟିଂ ଏକ୍ଜିକ୍ୟୁଟିଭ ରେଖାଙ୍କୁ କମ୍ପାନୀର ନିର୍ଦ୍ଦେଶକମାନଙ୍କ ଆଗରେ ବାର୍ଷିକ ଫଳାଫଳ ଉପସ୍ଥାପନ କରିବାର ଥିଲା। ସେ ଏକ ସରଳ ରୂପରେଖ ଏବଂ ମାତ୍ର ଆଠଟି ସ୍ଲାଇଡ ପ୍ରସ୍ତୁତ କଲେ, ପ୍ରତ୍ୟେକରେ ଗୋଟିଏ ସ୍ପଷ୍ଟ ଚାର୍ଟ। ଆଗ ରାତିରେ ସେ ତାଙ୍କ ଭଉଣୀ ଆଗରେ ପୁରା ଭାଷଣଟି ତିନିଥର ଅଭ୍ୟାସ କଲେ। ସେଦିନ ସେ ଆରମ୍ଭ କରିବାର ପାଞ୍ଚ ମିନିଟ ଆଗରୁ ମିଟିଂ ରୁମର ପ୍ରୋଜେକ୍ଟର କାମ କରିବା ବନ୍ଦ କରିଦେଲା। ଭାଗ୍ୟକୁ ରେଖା ସବୁ ଜରୁରୀ ସଂଖ୍ୟା ଥିବା ହ୍ୟାଣ୍ଡଆଉଟ ପ୍ରିଣ୍ଟ କରି ଆଣିଥିଲେ। ସେ ଏକ ସଂକ୍ଷିପ୍ତ ବିବରଣୀରେ ଆରମ୍ଭ କଲେ ଏବଂ ତା'ପରେ ଡେଲିଭରି ଖର୍ଚ୍ଚ କେତେ କମିଛି ସେଥିରେ ଗୁରୁତ୍ୱ ଦେଲେ। ଜଣେ ନିର୍ଦ୍ଦେଶକ ବେଳଗାଭିର ନୂଆ ଦୋକାନ ବିଷୟରେ ପଚାରିବାରୁ ସେ ଶାନ୍ତ ଭାବେ ସଂଖ୍ୟାଗୁଡ଼ିକ ସ୍ପଷ୍ଟ କଲେ। ସେ ତାଙ୍କ ତିନୋଟି ମୁଖ୍ୟ କଥାର ସାରାଂଶ କହି ଶେଷ କଲେ, ଆଉ ନିର୍ଦ୍ଦେଶକମାନେ ଏତେ ସ୍ପଷ୍ଟ ଭାବେ କହିଥିବାରୁ ତାଙ୍କୁ ଧନ୍ୟବାଦ ଦେଲେ।",
