        "workplace|3:1|5|scenario": "ସଞ୍ଜୟ ପୁଣେ ଅଫିସରେ ତାଙ୍କ ମ୍ୟାନେଜର ଲକ୍ଷ୍ମୀଙ୍କ ସହ ଏକ କ୍ଲାଏଣ୍ଟ ପ୍ରେଜେଣ୍ଟେସନର ଅଭ୍ୟାସ କରନ୍ତି।",
        "workplace|3:1|5|l0": "ଠିକ ଅଛି, ସଞ୍ଜୟ, ଭାବ ମୁଁ କ୍ଲାଏଣ୍ଟ। ପ୍ରସ୍ତୁତ ହେଲେ ଆରମ୍ଭ କର।",
        "workplace|3:1|5|l1": "ସମସ୍ତଙ୍କୁ ସୁପ୍ରଭାତ, ଆଉ ଆମକୁ ଡାକିଥିବାରୁ ଧନ୍ୟବାଦ। ଆଜି ମୁଁ ଆପଣଙ୍କ ନୂଆ ୱେବସାଇଟ ପାଇଁ ଆମ ଯୋଜନା ଆପଣଙ୍କୁ ବୁଝାଇବାକୁ ଚାହେଁ।",
        "workplace|3:1|5|l2": "ଭଲ ଆରମ୍ଭ। ଭାଷଣଟି କିପରି ସଜାଇବ?",
        "workplace|3:1|5|l3": "ମୁଁ ତିନୋଟି କଥା କହିବି: ଆମେ କ'ଣ ପାଇଲୁ, ଆମେ କ'ଣ ପରାମର୍ଶ ଦେଉଛୁ, ଆଉ ଏଥିରେ କେତେ ଖର୍ଚ୍ଚ ହେବ।",
