        "workplace|3:1|5|l5": "ମୁଁ ତାଙ୍କୁ ଧନ୍ୟବାଦ ଦେବି, ପ୍ରଶ୍ନଟି ଲେଖି ରଖିବି ଏବଂ କହିବି ଯେ ଶେଷରେ ତା'ର ଉତ୍ତର ଦେବି।",
