        "workplace|3:1|5|l7": "ତିନୋଟି କଥାର ସାରାଂଶ ଆଉ ଏକ ସ୍ପଷ୍ଟ ପରବର୍ତ୍ତୀ ପଦକ୍ଷେପ: ଆସନ୍ତା ଶୁକ୍ରବାର ଏକ ମିଟିଂ।",
