        "workplace|4:1|1|p1": "ଗୁରୁବାର ସୁଦ୍ଧା ଆମେ ଆପଣଙ୍କୁ ଏକ ବିସ୍ତୃତ ପ୍ରସ୍ତାବ ଆଉ କୋଟେସନ ପଠାଇବୁ।",
        "workplace|4:1|1|p2": "ଆମ ଆନୁମାନିକ ସମୟସୂଚୀ ଛଅ ସପ୍ତାହ, କିନ୍ତୁ ସାଇଟ ଦେଖିବା ପରେ ମୁଁ ନିଶ୍ଚିତ କରିବି।",
