        "workplace|4:1|3|p1": "ଇନଭଏସରେ ଭୁଲ ରାଶି ଦେଖାଉଛି, ତେଣୁ ମୁଁ ଆକାଉଣ୍ଟସକୁ ତାହା ସୁଧାରିବାକୁ କହିବି।",
        "workplace|4:1|3|p2": "ମୁଁ ଆପଣଙ୍କ ବିରକ୍ତି ବୁଝିପାରୁଛି, ଆଉ ଆଜି ହିଁ ଏହା ମୋ ମ୍ୟାନେଜରଙ୍କ ପାଖକୁ ପଠାଇବି।",
        "workplace|4:1|3|p3": "ଡେରି ପାଇଁ କ୍ଷତିପୂରଣ ଭାବେ, ଏଥର ଆମେ ଡେଲିଭରି ଚାର୍ଜ ଛାଡ଼ କରିଦେବୁ।",
        "workplace|4:1|3|p4": "ମୁଁ ଆପଣଙ୍କୁ ଭରସା ଦେଉଛି ଯେ ଶୁକ୍ରବାର ସୁଦ୍ଧା ରିପ୍ଲେସମେଣ୍ଟ ଆପଣଙ୍କ ପାଖରେ ପହଞ୍ଚିବ; ଏହା ମୋର ବ୍ୟକ୍ତିଗତ ପ୍ରତିବଦ୍ଧତା।",
        "workplace|4:1|4|title": "କେବେ ନ ଆସିଥିବା ମେନୁ କାର୍ଡ",
        "workplace|4:1|4|text": "ଇମରାନ ବେଙ୍ଗାଲୁରୁର ଏକ ପ୍ରିଣ୍ଟିଂ କମ୍ପାନୀରେ ଗ୍ରାହକଙ୍କ ଆକାଉଣ୍ଟ ସମ୍ଭାଳନ୍ତି। ଗୋଟିଏ ସୋମବାର, ମହୀଶୂରରେ ଏକ ହୋଟେଲ ଚଳାଉଥିବା ଶ୍ରୀମତୀ ଶେଟ୍ଟି ବହୁତ ବିରକ୍ତ ହୋଇ ତାଙ୍କୁ ଫୋନ କଲେ। କୋଟେସନରେ ଏକ ସପ୍ତାହ ଭିତରେ ଡେଲିଭରିର କଥା ଥିଲେ ବି ତାଙ୍କ ନୂଆ ମେନୁ କାର୍ଡ ଆସିନଥିଲା। ଇମରାନ ବାଧା ନ ଦେଇ ଶୁଣିଲେ, ତା'ପରେ ସେ ଠିକ ବୁଝିଛନ୍ତି କି ନାହିଁ ଜାଣିବାକୁ ତାଙ୍କ ଆବଶ୍ୟକତା ପୁଣି କହିଲେ। ସେ ଜାଣିଲେ ଯେ ଇନଭଏସରେ ଭୁଲ ଯୋଗୁଁ ଅର୍ଡରଟି କେବେ ପଠାଯାଇ ନ ଥିଲା। ସେ ସମସ୍ୟାଟି ତାଙ୍କ ମ୍ୟାନେଜରଙ୍କ ପାଖକୁ ପଠାଇଲେ ଏବଂ ସେହି ଅପରାହ୍ନରେ ହିଁ କୁରିଅରର ବ୍ୟବସ୍ଥା କଲେ। ଡେରି ପାଇଁ ଶ୍ରୀମତୀ ଶେଟ୍ଟିଙ୍କୁ କ୍ଷତିପୂରଣ ଭାବେ କମ୍ପାନୀ ବିଲରୁ ଦଶ ପ୍ରତିଶତ କମାଇଦେଲା। ଇମରାନ ତାଙ୍କୁ ଭରସା ଦେଲେ ଯେ ସେ ନିଜେ ତାଙ୍କ ଭବିଷ୍ୟତ ଅର୍ଡରଗୁଡ଼ିକ ଯାଞ୍ଚ କରିବେ, ଆଉ ସେ କମ୍ପାନୀ ସହ ରହିଲେ।",
        "workplace|4:1|4|q0": "ଶ୍ରୀମତୀ ଶେଟ୍ଟି କାହିଁକି ବିରକ୍ତ ଥିଲେ?",
        "workplace|4:1|4|q0o0": "ତାଙ୍କ ମେନୁ କାର୍ଡ ଆସିନଥିଲା",
