        "workplace|4:1|4|q2": "ଡେରି ପାଇଁ କମ୍ପାନୀ କିପରି କ୍ଷତିପୂରଣ କଲା?",
        "workplace|4:1|4|q2o0": "ବିଲରୁ ଦଶ ପ୍ରତିଶତ କମାଇଦେଲା",
