        "workplace|4:1|4|q2o2": "ଏକ ନୂଆ ପ୍ରିଣ୍ଟର ପଠାଇଲା",
        "workplace|4:1|4|q2o3": "ତାଙ୍କ ସବୁ ଟଙ୍କା ଫେରାଇଦେଲା",
        "workplace|4:1|5|title": "ନୂଆ ଗ୍ରାହକ",
        "workplace|4:1|5|scenario": "ହୁବ୍ବଳିର ଏକ ଫର୍ଣ୍ଣିଚର କମ୍ପାନୀର ସେଲ୍ସ ମ୍ୟାନେଜର ନେହା, ନୂଆ ଅଫିସ ପାଇଁ ଫର୍ଣ୍ଣିଚର ଦରକାର ଥିବା ବିକ୍ରମ କୁଲକର୍ଣ୍ଣୀଙ୍କ ଫୋନ ଉଠାନ୍ତି।",
        "workplace|4:1|5|l0": "ନମସ୍କାର, ଶ୍ରୀ କୁଲକର୍ଣ୍ଣୀ। ଯୋଗାଯୋଗ କରିଥିବାରୁ ଧନ୍ୟବାଦ। ଆମେ କିପରି ସାହାଯ୍ୟ କରିପାରିବୁ?",
        "workplace|4:1|5|l1": "ଆମେ ବେଳଗାଭିରେ ଏକ ନୂଆ ଅଫିସ ଖୋଲୁଛୁ ଏବଂ ଚାଳିଶ ଜଣଙ୍କ ପାଇଁ ଡେସ୍କ ଆଉ ଚେୟାର ଦରକାର।",
        "workplace|4:1|5|l2": "ବହୁତ ଭଲ। ଆପଣଙ୍କ ଆବଶ୍ୟକତା ବିଷୟରେ ଆଉ ଟିକେ କହିବେ କି? ମନରେ କିଛି ବଜେଟ କିମ୍ବା ଷ୍ଟାଇଲ ଅଛି କି?",
        "workplace|4:1|5|l3": "କିଛି ସରଳ ଆଉ ଆରାମଦାୟକ। ଆମ ବଜେଟ ପ୍ରାୟ ଆଠ ଲକ୍ଷ ଟଙ୍କା।",
        "workplace|4:1|5|l4": "ଏହା ବେଶ ସମ୍ଭବ। ଆପଣଙ୍କୁ ସବୁକିଛି କେବେ ସୁଦ୍ଧା ଡେଲିଭରି ଦରକାର?",
        "workplace|4:1|5|l5": "ଆସନ୍ତା ମାସ ପନ୍ଦର ତାରିଖ ସୁଦ୍ଧା। ସେହି ତାରିଖଟି ଆମ ପାଇଁ ବହୁତ ଜରୁରୀ।",
        "workplace|4:1|5|l6": "ବୁଝିଲି। ଶୁକ୍ରବାର ସୁଦ୍ଧା ମୁଁ ଆପଣଙ୍କୁ ଦୁଇଟି ବିକଳ୍ପ ସହ ଏକ ପ୍ରସ୍ତାବ ଆଉ କୋଟେସନ ପଠାଇବି।",
        "workplace|4:1|5|l7": "ଆପଣଙ୍କ ଟିମ ସାଇଟରେ ଫିଟିଂ କାମ ମଧ୍ୟ କରିପାରିବେ କି?",
        "workplace|4:1|5|l8": "ହଁ, ଇନଷ୍ଟଲେସନ ସାମିଲ ଅଛି। ଆଉ ମୁଁ ଭରସା ଦେଉଛି ଯେ ଆମେ ଆପଣଙ୍କ ସମୟସୀମା ପୂରଣ କରିବୁ।",
        "workplace|4:1|5|l9": "ବଢ଼ିଆ। ତେବେ ଆପଣଙ୍କ ପ୍ରସ୍ତାବକୁ ଅପେକ୍ଷା କରିବି।",
        "workplace|4:1|5|q0": "ଫର୍ଣ୍ଣିଚର କେତେ ଜଣଙ୍କ ପାଇଁ?",
