        "workplace|5:1|1|p0": "ମୋତେ ବହୁତ ଜ୍ୱର ହୋଇଛି, ତେଣୁ ମୁଁ ଆଜି ଅସୁସ୍ଥତା ଛୁଟି ନେବାକୁ ଚାହେଁ।",
        "workplace|5:1|1|p1": "ମୋ ଭାଇର କଲେଜ ଆଡମିସନ ପାଇଁ ଶୁକ୍ରବାର ମୁଁ ଅଧା ଦିନ ଛୁଟି ନେଇପାରିବି କି?",
        "workplace|5:1|1|p2": "ଟ୍ରେନ ଟିକଟ ବୁକ କରିବା ଆଗରୁ ମୁଁ ମୋ ବାକି ଛୁଟି ଦେଖିନିଏ।",
        "workplace|5:1|1|p3": "ମୋ ମ୍ୟାନେଜର ଦଶ ତାରିଖରୁ ଚଉଦ ତାରିଖ ପର୍ଯ୍ୟନ୍ତ ମୋ ଛୁଟି ମଞ୍ଜୁର କରିଛନ୍ତି।",
        "workplace|5:1|1|p4": "ଦୁଃଖିତ, ମୁଁ ସୋମବାର ଅନୁପସ୍ଥିତ ଥିଲି; ବାକି କାମ ସାରିବାକୁ କାଲି ଘରୁ କାମ କରିପାରିବି କି?",
