        "workplace|5:1|2|w5": "ଆଗରୁ",
        "workplace|5:1|3|p0": "ଆସନ୍ତା ଶନିବାର ମୋ ସହ ସିଫ୍ଟ ଅଦଳବଦଳ କରିବାକୁ ତୁମର ଅସୁବିଧା ନାହିଁ ତ?",
        "workplace|5:1|3|p1": "ମୁଁ ନ ଥିବା ବେଳେ ମୋ କଲଗୁଡ଼ିକ ସମ୍ଭାଳିବାକୁ ପ୍ରିୟା ରାଜି ହୋଇଛନ୍ତି।",
        "workplace|5:1|3|p2": "କିଛି ବାଦ ନ ପଡ଼ିବା ପାଇଁ ମୁଁ ଗୁରୁବାର ଠିକ ଭାବେ ଦାୟିତ୍ୱ ହସ୍ତାନ୍ତର କରିବି।",
        "workplace|5:1|3|p3": "ଆମ ସମୀକ୍ଷା ଆସନ୍ତା ସପ୍ତାହକୁ ଘୁଞ୍ଚାଇପାରିବା କି? ମୁଁ ସୋମବାର ଛୁଟିରେ ଅଛି।",
        "workplace|5:1|3|p4": "ଅତି କମରେ ଏକ ସପ୍ତାହ ଆଗରୁ ପଚାରିଲେ, ଆମ ମ୍ୟାନେଜର ନମନୀୟ।",
        "workplace|5:1|4|title": "ଉଡୁପିରେ ବାହାଘର",
        "workplace|5:1|4|text": "ସୌମ୍ୟା ବେଙ୍ଗାଲୁରୁରେ ଏକ ବ୍ୟାଙ୍କର ମୁଖ୍ୟ କାର୍ଯ୍ୟାଳୟରେ ପେମେଣ୍ଟସ ଟିମରେ କାମ କରନ୍ତି। ଉଡୁପିରେ ତାଙ୍କ ମାମୁଁ ଝିଅର ବାହାଘର ମାର୍ଚ୍ଚର ଶେଷ ସପ୍ତାହରେ ପଡ଼ିଲା, ଯାହା ବର୍ଷର ସବୁଠାରୁ ବ୍ୟସ୍ତ ସମୟ। ସେ ତାଙ୍କ ବାକି ଛୁଟି ଦେଖିଲେ ଏବଂ ଜାଣିଲେ ଯେ ତାଙ୍କର ଏବେ ବି ନଅ ଦିନ ଅଛି। ତିନି ସପ୍ତାହ ଆଗରୁ ସେ ତାଙ୍କ ମ୍ୟାନେଜର ଶ୍ରୀ ଭଟ୍ଟଙ୍କୁ ଚାରି ଦିନ ଛୁଟି ମାଗିଲେ ଏବଂ ଭଦ୍ର ଭାବେ କାରଣ ବୁଝାଇଲେ। ବାହାଘର ପରଦିନ ଘରୁ କାମ କରିବାକୁ ମଧ୍ୟ ସେ ପ୍ରସ୍ତାବ ଦେଲେ। ଶ୍ରୀ ଭଟ୍ଟ ନମନୀୟ ଥିଲେ, କିନ୍ତୁ ମାସ ଶେଷ ରିପୋର୍ଟଗୁଡ଼ିକ କିଏ ସମ୍ଭାଳିବ ବୋଲି ପଚାରିଲେ। ସୌମ୍ୟା ତାଙ୍କ ସହକର୍ମୀ ରାକେଶଙ୍କ ସହ ଦୁଇଟି ସିଫ୍ଟ ଅଦଳବଦଳ କଲେ ଏବଂ ଯିବା ଆଗରୁ ପୁରା ଦାୟିତ୍ୱ ହସ୍ତାନ୍ତର କରିବାକୁ କଥା ଦେଲେ। ତାଙ୍କ ଯୋଜନାରେ ଖୁସି ହୋଇ ଶ୍ରୀ ଭଟ୍ଟ ସେହି ଅପରାହ୍ନରେ ହିଁ ଛୁଟି ମଞ୍ଜୁର କଲେ।",
        "workplace|5:1|4|q0": "ସୌମ୍ୟାଙ୍କୁ କାହିଁକି ଛୁଟି ଦରକାର ଥିଲା?",
        "workplace|5:1|4|q0o0": "ଉଡୁପିରେ ତାଙ୍କ ମାମୁଁ ଝିଅର ବାହାଘର ପାଇଁ",
        "workplace|5:1|4|q0o1": "କାରଣ ସେ ଅସୁସ୍ଥ ଥିଲେ",
        "workplace|5:1|4|q0o2": "ଏକ ତାଲିମ କୋର୍ସ ପାଇଁ",
        "workplace|5:1|4|q0o3": "ନୂଆ ଘରକୁ ଯିବା ପାଇଁ",
