        "workplace|5:1|5|title": "ସକାଳୁ ସକାଳୁ ଫୋନ",
        "workplace|5:1|5|scenario": "ଅରୁଣଙ୍କ ମା ଅସୁସ୍ଥ ଥିବାରୁ ସେ ସକାଳୁ ସକାଳୁ ତାଙ୍କ ଟିମ ଲିଡ ଶାଳିନୀଙ୍କୁ ଫୋନ କରନ୍ତି।",
        "workplace|5:1|5|l0": "ସୁପ୍ରଭାତ, ଶାଳିନୀ। ଏତେ ସକାଳୁ ଫୋନ କରିଥିବାରୁ ଦୁଃଖିତ। ଆପଣଙ୍କ ପାଖରେ ଟିକେ ସମୟ ଅଛି କି?",
        "workplace|5:1|5|l1": "ନିଶ୍ଚୟ, ଅରୁଣ। ସବୁ ଠିକ ଅଛି ତ?",
        "workplace|5:1|5|l2": "ସେମିତି ନୁହେଁ। କାଲି ରାତିରେ ମୋ ମା ପଡ଼ିଗଲେ, ଆଉ କିଛି ପରୀକ୍ଷା ପାଇଁ ତାଙ୍କୁ ହସପିଟାଲ ନେବାକୁ ପଡ଼ିବ।",
        "workplace|5:1|5|l3": "ଓହୋ, ଶୁଣି ଦୁଃଖ ଲାଗିଲା। ଦୟାକରି ତାଙ୍କ ଯତ୍ନ ନିଅ। ତୁମକୁ ପୁରା ଦିନ ଦରକାର ହେବ କି?",
        "workplace|5:1|5|l4": "ସେମିତି ଲାଗୁଛି। ମୁଁ ଆଜି ଛୁଟି ନେବାକୁ ଚାହେଁ, ଆଉ ହୁଏତ କାଲି ଘରୁ କାମ କରିବି।",
        "workplace|5:1|5|l5": "ଠିକ ଅଛି। ତିନିଟାର କ୍ଲାଏଣ୍ଟ କଲର କ'ଣ ହେବ?",
        "workplace|5:1|5|l6": "ଦୀପକ ପ୍ରୋଜେକ୍ଟଟି ଭଲ ଭାବେ ଜାଣନ୍ତି। ମୁଁ ତାଙ୍କୁ ଆଗରୁ ପଚାରିସାରିଛି, ଆଉ ସେ ଖୁସିରେ ତାହା ସମ୍ଭାଳିବେ।",
        "workplace|5:1|5|l7": "ଭଲ। ତୁମ ନୋଟ ତାଙ୍କୁ ପଠାଇଦିଅ, ଆଉ ସମୟ ପାଇଲେ ପୋର୍ଟାଲରେ ଛୁଟି ପାଇଁ ଆବେଦନ କର।",
        "workplace|5:1|5|l8": "ମୁଁ ଘଣ୍ଟାଏ ଭିତରେ କରିଦେବି। ବୁଝିଥିବାରୁ ଧନ୍ୟବାଦ, ଶାଳିନୀ।",
        "workplace|5:1|5|l9": "କିଛି ଅସୁବିଧା ନାହିଁ। ଆଶା କରୁଛି ତୁମ ମା ଶୀଘ୍ର ଭଲ ହୋଇଯିବେ।",
        "workplace|5:1|5|q0": "ଅରୁଣଙ୍କୁ କାହିଁକି ଛୁଟି ଦରକାର?",
