        "workplace|6:1|1|p0": "ମୋଟାମୋଟି, ଏ ବର୍ଷ ତୁମ କାର୍ଯ୍ୟଦକ୍ଷତା ବହୁତ ଭଲ ରହିଛି।",
        "workplace|6:1|1|p1": "ରାଗିଥିବା ଗ୍ରାହକଙ୍କ ସହ ତୁମେ ଯେମିତି ଶାନ୍ତ ଭାବେ ବ୍ୟବହାର କର, ତାହା ହିଁ ତୁମର ସବୁଠାରୁ ବଡ଼ ଶକ୍ତି।",
        "workplace|6:1|1|p2": "କାଲିର ପ୍ରେଜେଣ୍ଟେସନ ଉପରେ ମୁଁ ତୁମକୁ କିଛି ଗଠନମୂଳକ ମତାମତ ଦେଇପାରିବି କି?",
        "workplace|6:1|1|p3": "ମୋ ଆତ୍ମମୂଲ୍ୟାୟନରେ ମୁଁ ସମୟ ପରିଚାଳନାକୁ ଏକ ଦୁର୍ବଳତା ଭାବେ ଲେଖିଛି।",
        "workplace|6:1|1|p4": "ଠିକ ସମୟରେ ମହୀଶୂର ଶାଖା ଆରମ୍ଭ କରିବା ଆମ ଟିମ ପାଇଁ ଏକ ପ୍ରକୃତ ମାଇଲଖୁଣ୍ଟ ଥିଲା।",
        "workplace|6:1|2|w0": "ପରାମର୍ଶଦାତା",
        "workplace|6:1|2|w1": "ନୂଆ ଦକ୍ଷତା ଶିଖିବା",
        "workplace|6:1|2|w2": "ସର୍ଟିଫିକେସନ",
        "workplace|6:1|2|w3": "ସମ୍ଭାବନା",
        "workplace|6:1|2|w4": "ଦରମା ବୃଦ୍ଧି",
        "workplace|6:1|2|w5": "ଯୋଗ୍ୟ ହେବା",
        "workplace|6:1|3|p0": "ମୁଁ ଡାଟା ଆନାଲିସିସରେ ନୂଆ ଦକ୍ଷତା ଶିଖିବାକୁ ଚାହେଁ; କମ୍ପାନୀ ଏକ ଛୋଟ କୋର୍ସରେ ସାହାଯ୍ୟ କରିପାରିବ କି?",
        "workplace|6:1|3|p1": "ଲିଡ ଭୂମିକା ପାଇଁ ଆବେଦନ କରିବା ଆଗରୁ ଏକ କ୍ଲାଉଡ ସର୍ଟିଫିକେସନ କରିବାକୁ ମୋ ପରାମର୍ଶଦାତା କହିଲେ।",
        "workplace|6:1|3|p2": "ତୁମ ମ୍ୟାନେଜର ଭାବନ୍ତି ଯେ ଦୁଇ ବର୍ଷ ଭିତରେ ଏକ ଟିମକୁ ନେତୃତ୍ୱ ଦେବାର ସମ୍ଭାବନା ତୁମ ଭିତରେ ଅଛି।",
        "workplace|6:1|3|p3": "ଏ ବର୍ଷ ଟିମର ସମସ୍ତେ ଅତି କମରେ ଆଠ ପ୍ରତିଶତ ଦରମା ବୃଦ୍ଧି ପାଇବେ।",
        "workplace|6:1|3|p4": "ମୁଁ ବିଶ୍ୱାସ କରେ ମୁଁ ପଦୋନ୍ନତିର ଯୋଗ୍ୟ, ଆଉ ପରବର୍ତ୍ତୀ ପଦକ୍ଷେପ କ'ଣ, ସେ ବିଷୟରେ ଆଲୋଚନା କରିବାକୁ ଚାହେଁ।",
        "workplace|6:1|4|title": "ମୂଲ୍ୟାୟନ ଦିନ",
        "workplace|6:1|4|text": "ପ୍ରତି ଅପ୍ରେଲରେ ମଙ୍ଗଳୁରୁରେ ଫରିଦାଙ୍କ କମ୍ପାନୀ ବାର୍ଷିକ ମୂଲ୍ୟାୟନ ମିଟିଂ କରେ। ତାଙ୍କ ମିଟିଂ ଆଗରୁ ସେ ଏକ ସଚ୍ଚୋଟ ଆତ୍ମମୂଲ୍ୟାୟନ ଲେଖିଲେ, ଯେଉଁଥିରେ ତାଙ୍କ ଶକ୍ତି ଓ ଗୋଟିଏ ସ୍ପଷ୍ଟ ଦୁର୍ବଳତା ଲେଖିଥିଲେ: ସେ କ୍ୱଚିତ ସାହାଯ୍ୟ ମାଗନ୍ତି। ତାଙ୍କ ମ୍ୟାନେଜର ଶ୍ରୀ ରାଓ ନୂଆ ବିଲିଂ ସିଷ୍ଟମରେ ତାଙ୍କ କାର୍ଯ୍ୟଦକ୍ଷତାର ପ୍ରଶଂସା କରି ଆରମ୍ଭ କଲେ, ଯାହା ଟିମ ପାଇଁ ଏକ ବଡ଼ ମାଇଲଖୁଣ୍ଟ ଥିଲା। ତା'ପରେ ସେ ସମସ୍ୟା ଆଗରୁ ଜଣାଇବା ବିଷୟରେ କିଛି ଗଠନମୂଳକ ମତାମତ ଦେଲେ। ଫରିଦା ତାଙ୍କୁ ଧନ୍ୟବାଦ ଦେଲେ ଏବଂ ପ୍ରୋଜେକ୍ଟ ମ୍ୟାନେଜମେଣ୍ଟରେ ତାଲିମ ମାଗିଲେ। ଶ୍ରୀ ରାଓ ଏକ ସର୍ଟିଫିକେସନ କୋର୍ସର ଖର୍ଚ୍ଚ ଦେବାକୁ ଏବଂ ତାଙ୍କ ପାଇଁ ଜଣେ ସିନିୟର ପରାମର୍ଶଦାତା ଖୋଜିବାକୁ ରାଜି ହେଲେ। ସେ କହିଲେ ଯେ ଦିନେ ଏକ ଟିମକୁ ନେତୃତ୍ୱ ଦେବାର ସମ୍ଭାବନା ତାଙ୍କ ଭିତରେ ଅଛି ଏବଂ ସେ ଭଲ ଦରମା ବୃଦ୍ଧିର ଯୋଗ୍ୟ। ଫରିଦା ଆଗାମୀ ବର୍ଷ ପାଇଁ ଏକ ସ୍ପଷ୍ଟ ଯୋଜନା ନେଇ ମିଟିଂରୁ ବାହାରିଲେ।",
        "workplace|6:1|4|q0": "ଫରିଦା କେଉଁ ଦୁର୍ବଳତା ଲେଖିଥିଲେ?",
        "workplace|6:1|4|q0o0": "ସେ କ୍ୱଚିତ ସାହାଯ୍ୟ ମାଗନ୍ତି",
