        "workplace|6:1|4|q2": "ଶ୍ରୀ ରାଓ କ'ଣ କରିବାକୁ ରାଜି ହେଲେ?",
        "workplace|6:1|4|q2o0": "କୋର୍ସର ଖର୍ଚ୍ଚ ଦେବା ଆଉ ପରାମର୍ଶଦାତା ଖୋଜିବା",
        "workplace|6:1|4|q2o1": "ତୁରନ୍ତ ତାଙ୍କୁ ମ୍ୟାନେଜର କରିବା",
        "workplace|6:1|4|q2o2": "ତାଙ୍କୁ ଅନ୍ୟ ଟିମକୁ ପଠାଇବା",
        "workplace|6:1|4|q2o3": "ତାଙ୍କ ମୂଲ୍ୟାୟନ ବାତିଲ କରିବା",
        "workplace|6:1|5|title": "ବାର୍ଷିକ ସମୀକ୍ଷା",
        "workplace|6:1|5|scenario": "ରମେଶଙ୍କର ବେଙ୍ଗାଲୁରୁ ଅଫିସରେ ତାଙ୍କ ମ୍ୟାନେଜର ସୁନୀତାଙ୍କ ସହ ବାର୍ଷିକ ମୂଲ୍ୟାୟନ ମିଟିଂ ଅଛି।",
        "workplace|6:1|5|l0": "ଆସିଥିବାରୁ ଧନ୍ୟବାଦ, ରମେଶ। ତୁମ ଆତ୍ମମୂଲ୍ୟାୟନରୁ ଆରମ୍ଭ କରିବା। ତୁମକୁ ବର୍ଷଟି କେମିତି ଲାଗିଲା?",
        "workplace|6:1|5|l1": "ମୋତେ ଲାଗୁଛି ଭଲ ଗଲା। ଆମେ ଠିକ ସମୟରେ ପେମେଣ୍ଟ ଆପ ଦେଲୁ, ଆଉ ମୁଁ ଦୁଇଜଣ ନୂଆ କର୍ମଚାରୀଙ୍କୁ ତାଲିମ ଦେଲି।",
        "workplace|6:1|5|l2": "ମୁଁ ସହମତ। ଆପରେ ତୁମ କାର୍ଯ୍ୟଦକ୍ଷତା ଚମତ୍କାର ଥିଲା, ଆଉ କ୍ଲାଏଣ୍ଟ ବିଶେଷ ଭାବେ ତୁମ କାମର କଥା କହିଲେ।",
        "workplace|6:1|5|l3": "ଶୁଣି ବହୁତ ଭଲ ଲାଗିଲା। ମୁଁ କିଛି ସୁଧାରିବା ଦରକାର କି?",
        "workplace|6:1|5|l4": "କେବଳ ଗୋଟିଏ କଥା। ମିଟିଂରେ ଭଲ ଆଇଡିଆ ଥିଲେ ବି ତୁମେ ଅନେକ ସମୟରେ ଚୁପ ରହ। ମୁଁ ଚାହେଁ ତୁମେ ଆହୁରି ଖୋଲି କୁହ।",
        "workplace|6:1|5|l5": "ଠିକ କଥା। ମୁଁ ମୋ ଆଇଡିଆ ଆଗରୁ କହିବାକୁ ଚେଷ୍ଟା କରିବି। ମୁଁ କିଛି ତାଲିମ ମଧ୍ୟ ମାଗିପାରେ କି?",
        "workplace|6:1|5|l6": "ନିଶ୍ଚୟ। ତୁମ ମନରେ କ'ଣ ଅଛି?",
        "workplace|6:1|5|l7": "ଜନସମକ୍ଷରେ କହିବାର ଏକ କୋର୍ସ, ଆଉ ହୁଏତ ସିନିୟର ଟିମରୁ ଜଣେ ପରାମର୍ଶଦାତା।",
        "workplace|6:1|5|l8": "ଦୁଇଟିଯାକ ଭଲ ଆଇଡିଆ। ମୁଁ ଏହି ସପ୍ତାହରେ ଏଚଆରଙ୍କ ସହ କଥା ହେବି। ଏମିତି ଚାଲୁରଖ, ଆସନ୍ତା ବର୍ଷ ଆମେ ଟିମ ଲିଡ ଭୂମିକା ବିଷୟରେ ଆଲୋଚନା କରିପାରିବା।",
        "workplace|6:1|5|l9": "ଧନ୍ୟବାଦ, ସୁନୀତା। ଆପଣଙ୍କ ସହଯୋଗ ପାଇଁ ମୁଁ ପ୍ରକୃତରେ କୃତଜ୍ଞ।",
        "workplace|6:1|5|q0": "କ୍ଲାଏଣ୍ଟ ବିଶେଷ ଭାବେ କ'ଣ କହିଲେ?",
